SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- maozi-cloud-nacos-middleware-db 可以改成自己的库名
DROP DATABASE IF EXISTS `maozi-cloud-nacos-middleware-db`;
CREATE DATABASE `maozi-cloud-nacos-middleware-db` CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE `maozi-cloud-nacos-middleware-db`;
-- maozi-cloud-nacos-middleware-db 可以改成自己的库名

-- ----------------------------
-- Table structure for config_info
-- ----------------------------
DROP TABLE IF EXISTS `config_info`;
CREATE TABLE `config_info` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `data_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8_bin NOT NULL COMMENT 'data_id',
  `group_id` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
  `content` longtext CHARACTER SET utf8mb3 COLLATE utf8_bin NOT NULL COMMENT 'content',
  `md5` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL COMMENT 'md5',
  `gmt_create` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `gmt_modified` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '修改时间',
  `src_user` text CHARACTER SET utf8mb3 COLLATE utf8_bin COMMENT 'source user',
  `src_ip` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL COMMENT 'source ip',
  `app_name` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
  `tenant_id` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT '' COMMENT '租户字段',
  `c_desc` varchar(256) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
  `c_use` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
  `effect` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
  `type` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8_bin DEFAULT NULL,
  `c_schema` text CHARACTER SET utf8mb3 COLLATE utf8_bin,
  `encrypted_data_key` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '密钥',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_configinfo_datagrouptenant` (`data_id`,`group_id`,`tenant_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8639 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC COMMENT='config_info';

-- ----------------------------
-- Records of config_info
-- ----------------------------
BEGIN;
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (3287, 'a.yml', 'DEFAULT_GROUP', 'a=abc', '1c8128107bd726f312947b043e28572a', '2026-02-28 07:44:31', '2026-02-28 07:45:11', 'nacos', '172.18.0.1', '', '75bc1675-1e8e-4099-b2f2-d9482ce14f4e', '', '', '', 'properties', '', '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (6377, 'seata.properties', 'SEATA_GROUP', '# Seata Server（TC）端配置，位于 middleware 命名空间 SEATA_GROUP\n# 服务端启动时读取本文件；各环境客户端经 cloud-seata.yml 读取本文件，获取事务分组映射\n\n# ---------- 事务日志存储 ----------\n# 存储模式：db（事务日志落库，重启不丢，生产推荐）\nstore.mode=db\n# 连接池类型\nstore.db.datasource=druid\n# 数据库类型\nstore.db.dbType=mysql\n# 数据库驱动：MySQL 8 及以上用 com.mysql.cj.jdbc.Driver，更低版本用 com.mysql.jdbc.Driver\nstore.db.driverClassName=com.mysql.cj.jdbc.Driver\n# 事务日志库连接（独立库 maozi-cloud-seata-middleware-db，建库脚本在 maozi-cloud-basic-seata 目录）\nstore.db.url=jdbc:mysql://maozi-cloud-basic-mysql:3306/maozi-cloud-seata-middleware-db?useUnicode=true&characterEncoding=utf8&connectTimeout=1000&socketTimeout=3000&autoReconnect=true&useSSL=false\n# 数据库账号\nstore.db.user=root\n# 数据库密码\nstore.db.password=password\n# 初始化连接数\nstore.db.minConn=1\n# 最大连接数\nstore.db.maxConn=20\n# 获取连接的最大等待时间（毫秒）\nstore.db.maxWait=5000\n# 全局事务表名\nstore.db.globalTable=global_table\n# 分支事务表名\nstore.db.branchTable=branch_table\n# 全局锁表名\nstore.db.lockTable=lock_table\n# 全局事务单次查询的最大条数\nstore.db.queryLimit=100\n\n# ---------- 事务分组 → TC 集群映射 ----------\n# local、dev 环境的事务组均路由到 default 集群\nservice.vgroupMapping.maozi-cloud-local-tx-group=default\nservice.vgroupMapping.maozi-cloud-dev-tx-group=default\n\n# ---------- undo 日志清理 ----------\n# undo 日志保留天数\nserver.undo.logSaveDays=7\n# undo 日志清理线程的执行间隔（毫秒）\nserver.undo.logDeletePeriod=86400000\n\n# ---------- 二阶段提交、回滚的重试超时 ----------\n# 二阶段提交重试超时时长（毫秒），-1 表示无限重试；达到超时后不再重试，存在数据不一致风险\nserver.maxCommitRetryTimeout=-1\n# 二阶段回滚重试超时时长（毫秒），-1 表示无限重试\nserver.maxRollbackRetryTimeout=-1\n\n# ---------- 超时事务恢复检测线程间隔 ----------\n# 提交中状态的全局事务：重试提交的间隔（毫秒）\nserver.recovery.committingRetryPeriod=1000\n# 异步提交状态的全局事务：重试提交的间隔（毫秒）\nserver.recovery.asynCommittingRetryPeriod=1000\n# 回滚中状态的全局事务：重试回滚的间隔（毫秒）\nserver.recovery.rollbackingRetryPeriod=1000\n# 超时事务检测间隔（毫秒），检出的超时事务转入回滚流程\nserver.recovery.timeoutRetryPeriod=1000', 'ed1aa4265d5ef7fe6104e36b11a5075d', '2026-07-13 12:01:58', '2026-11-24 08:51:34', NULL, '192.168.65.1', '', 'middleware', NULL, NULL, NULL, 'properties', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8539, 'boot-redis.yml', 'DEFAULT_GROUP', '# Redis 连接配置（Spring Data Redis + Lettuce 连接池），按生产环境 2C4G 规格调优\nspring:\n  data:\n    redis:\n      # Redis 地址，支持环境变量覆盖\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      # Redis 端口\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # Redis 密码，从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      # 逻辑库编号（0~15），按环境或业务隔离数据\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 客户端标识，便于通过 redis client list 排查\n      client-name: ${spring.application.name}-${application.environment}-${application.version}\n\n      # 命令执行超时（必须配置在 spring.data.redis.timeout），内网小命令 500ms 足够，大批量命令可放宽到 1s\n      timeout: 500ms\n      # TCP 建连超时，不配置默认 10s，故障时线程会长时间阻塞\n      connect-timeout: 2s\n\n      # Lettuce 客户端配置\n      lettuce:\n        # 应用关闭时等待在途命令执行完的超时时间，需小于 K8s terminationGracePeriodSeconds\n        shutdown-timeout: 1s\n        # 连接池配置\n        pool:\n          # 最大连接数：Lettuce 普通命令复用单条连接，连接池仅服务阻塞命令、事务与订阅\n          max-active: 64\n          # 获取连接的最大等待时间；不配置默认 -1（无限等待），生产必须显式配置\n          max-wait: 1000ms\n          # 最大空闲连接数\n          max-idle: 32\n          # 最小空闲连接数（预热连接）\n          min-idle: 8\n          # 空闲连接驱逐检测周期：维持 min-idle 并回收失效连接\n          time-between-eviction-runs: 30s', '1024144eb0c126ef403d04cea2a9e43c', '2026-10-28 12:59:14', '2026-11-24 08:56:42', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8540, 'cloud-default.yml', 'DEFAULT_GROUP', '# 所有服务共用的基础配置：Web 容器、优雅停机、MVC、JSON 序列化、Feign、日志级别（服务自身 yml 可覆盖）\n# Web 容器配置\nserver:\n  # 服务端口，优先级：环境变量 APPLICATION_PORT > application.port > 0（随机端口）\n  port: ${APPLICATION_PORT:${application.port:0}}\n  # 统一错误处理路径（落在免认证白名单 /application/** 内）\n  error.path: /application/error\n  # 优雅停机：graceful=等待在途请求处理完再关闭 / immediate=立即关闭\n  shutdown: graceful\n\n  # Undertow 容器配置（按生产环境 2C4G 规格调整）\n  undertow:\n    # IO 线程数：负责网络读写与事件分发，建议等于 CPU 核数\n    io-threads: 2\n    # 工作线程数：处理业务逻辑（DB、Redis、RPC 等），IO 密集型可调大（默认为 IO 线程数的 8 倍）\n    worker-threads: 64\n    # 缓冲区大小（字节），默认 1024 偏小\n    buffer-size: 16384\n    # 缓冲区使用堆外直接内存，降低 GC 压力\n    direct-buffers: true\n    # POST 请求最大体积（字节），大文件建议走 OSS 直传\n    max-http-post-size: 2097152\n    # Undertow 原生选项\n    options:\n      server:\n        # 已建立连接上等待下一个请求的超时时间（毫秒）\n        # 不应小于上游连接池的空闲时间，否则可能出现连接重置\n        no-request-timeout: 60000\n\n# Spring 通用配置\nspring:\n  # 生命周期配置\n  lifecycle:\n    # 优雅停机每个阶段的最长等待时间\n    timeout-per-shutdown-phase: 65s\n  # 启动配置\n  main:\n    # 关闭启动 banner，保持控制台干净\n    banner-mode: off\n    # 关闭启动信息日志（由 BaseApplication 统一输出）\n    log-startup-info: false\n  # Web 配置\n  web:\n    # 静态资源映射\n    resources:\n      # 不映射静态资源，纯接口服务\n      add-mappings: false\n  # Spring MVC 配置\n  mvc:\n    # 未匹配到处理器时抛出 NoHandlerFoundException，交给全局异常处理器返回 404\n    throw-exception-if-no-handler-found: true\n    # 路径匹配策略使用 AntPathMatcher（默认为 PathPatternParser）\n    pathmatch.matching-strategy: ant_path_matcher\n  # Jackson 序列化配置\n  jackson:\n    # 时区\n    time-zone: GMT+8\n    # 日期格式\n    date-format: yyyy-MM-dd HH:mm:ss\n    # null 字段不参与序列化\n    default-property-inclusion: NON_NULL\n\n# Feign 远程调用配置\nfeign:\n  # Feign 接口接入 Sentinel 熔断降级\n  sentinel:\n    enabled: true\n\n  # 以下四组为 OpenFeign 3.x 旧前缀属性，4.x 已改为 spring.cloud.openfeign.*，当前均不生效\n  # okhttp.enabled 对应 spring.cloud.openfeign.okhttp.enabled（启用 OkHttp 作为底层 HTTP 客户端）\n  okhttp:\n    enabled: true\n  # httpclient.enabled 对应 spring.cloud.openfeign.httpclient.hc5.enabled（默认关闭）\n  httpclient:\n    enabled: false\n  # client.config 对应 spring.cloud.openfeign.client.config（connect-timeout、read-timeout）\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  # compression 对应 spring.cloud.openfeign.compression（请求、响应压缩）\n  compression:\n    # 请求压缩\n    request:\n      enabled: true\n      min-request-size: 1024\n      mime-types: text/xml,application/xml,application/json\n    # 响应压缩\n    response:\n      enabled: true\n\n# 日志级别配置\nlogging:\n  # 各包日志级别\n  level:\n    # 根日志级别：仅输出错误\n    root: ERROR\n    # 项目代码日志级别\n    com.maozi: INFO\n    # Dubbo 注册日志关闭\n    org.apache.dubbo.registry: OFF\n    # Dubbo 通信日志关闭\n    org.apache.dubbo.remoting: OFF', '1a25f5db0c1705678da0dc5ff343bc3a', '2026-10-28 12:59:14', '2026-11-24 08:51:16', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8541, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '# Dubbo RPC 配置（按生产环境 2C4G 规格调整）\ndubbo:\n  # Dubbo 应用配置\n  application:\n    # Dubbo 应用名（前缀 dubbo- + 服务名）\n    name: dubbo-${spring.application.name}\n    # 注册模式：instance=应用级服务发现 / interface=接口级 / all=双注册（会增加注册中心压力）\n    register-mode: instance\n    # 应用版本（随 application.version），用于版本路由与灰度\n    version: ${application.version:main}\n    # 关闭序列化安全检查，避免自定义实体校验报错（仅限内网环境，端口暴露到外部时必须开启）\n    serialize-check-status: DISABLE\n    # 不校验序列化类是否实现 Serializable\n    check-serializable: false\n    # 关闭 QoS 运维端口（默认 22222，可 telnet 执行在线命令），减少攻击面\n    qos-enable: false\n    # QoS 禁止外部 IP 访问\n    qos-accept-foreign-ip: false\n    # 当前不生效：shutdown-wait 为 Dubbo 3.3 的属性\n    # 3.2.6 对应属性为 shutwait（用于设置系统参数 dubbo.service.shutdown.wait）\n    shutdown-wait: 15000\n  # RPC 实现类扫描包，按项目缩写拼接（如 system → com.maozi.system.*.api.impl.rpc）\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  # 通信协议配置\n  protocol:\n    # 通信协议：dubbo；需要 Triple/gRPC 时改为 tri\n    name: dubbo\n    # Dubbo 端口，-1 表示随机；固定端口用 APPLICATION_DUBBO_PORT 或 application.dubbo.port 指定\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n    # 线程池类型：固定大小线程池，避免 cached 无界线程耗尽容器资源\n    threadpool: fixed\n    # 线程池线程数\n    threads: 200\n    # 等待队列长度：0 表示线程占满后立即拒绝，避免请求堆积引发超时雪崩\n    queues: 0\n    # 单次请求最大载荷（字节），大报文接口需单独放宽\n    payload: 8388608\n  # 服务提供者配置\n  provider:\n    # 默认超时时间（毫秒）：3000 即 3s，核心读接口建议在 @DubboService 上单独收敛\n    timeout: 3000\n    # 默认不重试，该值会下发作为消费方默认值；仅幂等查询接口按接口开启重试\n    retries: 0\n    # 自定义过滤器：服务端从 RPC 附件还原用户、链路等上下文\n    filter: applicationDubboContextLoadFilter\n    # 优先使用的序列化方式\n    prefer-serialization: hessian2\n    # 序列化方式\n    serialization: hessian2\n  # 服务消费者配置\n  consumer:\n    # 启动时不检查依赖的服务是否在线，避免滚动发布时服务启动顺序耦合\n    check: false\n    # 默认超时时间（毫秒），3s，与 provider 对齐\n    timeout: 3000\n    # 默认不重试：重试会重复请求，非幂等写接口必须禁止；幂等查询可在 @DubboReference 上配置 retries=1\n    retries: 0\n    # 自定义过滤器：消费端将用户、链路等上下文写入 RPC 附件透传\n    filter: applicationDubboContextTransmitFilter\n  # 注册中心：复用 Nacos（与配置中心同实例），namespace 随环境隔离\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', 'c9b0f3429c2c6e1e54e70cedaf3ce560', '2026-10-28 12:59:14', '2026-11-24 08:55:11', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8542, 'cloud-nacos.yml', 'DEFAULT_GROUP', '# Nacos 服务发现配置（server-addr、namespace 由启动初始化器按环境写入）\nspring:\n  cloud:\n    nacos:\n      # 服务发现配置\n      discovery:\n        # 启用 Nacos 服务发现\n        enabled: true\n        # 启动时将本实例注册到注册中心\n        register-enabled: true\n        # 实例元数据：携带版本号，灰度路由按此筛选实例\n        metadata:\n          version: ${application.version:main}', 'fe9dc2a75e748eeb2a23b3f914658e4d', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8543, 'cloud-rocket.yml', 'DEFAULT_GROUP', '# RocketMQ 配置（当前未启用：无服务引入 stream 模块，接入 MQ 时替换 name-server）\nspring:\n  cloud:\n    stream:\n      rocketmq:\n        # RocketMQ Binder 配置\n        binder:\n          # access-key:    # 阿里云 AccessKey ID，按需配置\n          # secret-key:    # 阿里云 AccessKey Secret，按需配置\n          # NameServer 地址\n          name-server: localhost:9876\n# 以下为预留占位，未启用\n# rocketmq:\n  # instance:\n    # id:\n    # name:', '7ed1c9e411ede71a7a001c6cfa0fa149', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8544, 'cloud-sentinel.yml', 'DEFAULT_GROUP', '# Sentinel 流量防护配置（业务服务共用，网关见 maozi-cloud-gateway-service.yml）\n\n# RestTemplate 纳入 Sentinel 熔断限流（默认已开启）\nresttemplate:\n  sentinel:\n    enabled: true\n\n# Feign 接口接入 Sentinel 熔断降级\nfeign:\n  sentinel:\n    enabled: true\n\n# Sentinel 客户端：控制台接入、规则从 Nacos 加载\nspring:\n  cloud:\n    sentinel:\n      # 自定义键（非 Sentinel 官方属性）：Sentinel 应用名，同时作为下方规则 dataId 的前缀\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 应用启动即连接控制台（默认首次请求时才注册）\n      eager: true\n      # 与控制台的通信配置\n      transport:\n        # 客户端与控制台通信的本地端口，被占用时自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 资源名带 HTTP 方法前缀（如 GET:/user/info），区分同路径的不同请求方法\n      http-method-specify: true\n      # 规则数据源：规则存于 Nacos middleware 命名空间 SENTINEL_GROUP，变更后实时生效\n      # 各数据源通用字段：server-addr=Nacos 地址，namespace=命名空间，groupId=分组，\n      #                  dataId=规则文件名，rule-type=规则类型\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', 'e089fa4e387e2e024d989e306ec67830', '2026-10-28 12:59:14', '2026-11-24 08:49:52', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8545, 'boot-lock.yml', 'DEFAULT_GROUP', '# 分布式锁配置（Redisson 客户端连接、锁默认超时）\nlock:\n  # Redisson 配置\n  redisson:\n    # 单节点 Redis 地址，复用 spring.data.redis 的地址与端口\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    # Redis 密码\n    password: ${spring.data.redis.password}\n    # Redis 逻辑库编号\n    database: ${spring.data.redis.database:0}\n    # 集群模式：配置节点地址列表后自动启用，与 address 二选一\n    # node-addresses: redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # 获取锁的最长等待时间（秒），不配置默认 60\n    # waitTime: 60\n    # 锁的自动释放时间（秒），不配置默认 60\n    # leaseTime: 60', '3dd8b897d00f0f855638675d348e8b97', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8546, 'boot-monitor.yml', 'DEFAULT_GROUP', '# 监控配置：Spring Boot Admin 客户端注册、Actuator 端点与指标\nspring:\n  boot:\n    admin:\n      # Spring Boot Admin 客户端配置\n      client:\n        # SBA 服务端地址，启动后自动注册\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}/monitor\n        # 注册到 SBA 服务端所用的账号，须与服务端 spring.security.user 一致\n        username: monitor\n        password: monitor\n        # 应用关闭时自动从 SBA 服务端注销\n        auto-deregistration: true\n        # 注册实例信息\n        instance:\n          # 注册地址优先使用 IP（项目已固定取 spring.cloud.client.ip-address，此项仅作兜底）\n          prefer-ip: true\n          # 实例元数据：SBA 控制台展示的环境与版本\n          metadata:\n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            # 实例标签：环境、版本，可用于控制台筛选\n            tags:\n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\n# 当前不生效：endpoints.<id>.enabled 为 Boot 2.x 旧属性，Dubbo 端点由下方 management.endpoint.dubbo.enabled 控制\nendpoints:\n  dubbo:\n    enabled: true\n\n# Actuator 端点与指标\nmanagement:\n  # info 端点展示 info.* 配置项\n  info.env.enabled: true\n  # Dubbo 健康检查配置\n  health:\n    dubbo:\n      status:\n        # Dubbo 健康检查默认项：内存\n        defaults: memory\n        # 附加检查项：系统负载、线程池\n        extras: load,threadpool\n  # Web 端点暴露配置\n  endpoints:\n    web:\n      exposure:\n        # 暴露全部 Web 端点\n        include: \'*\'\n  # 各端点开关配置\n  endpoint:\n    # env 端点展示配置项的值\n    env.show-values: always\n    # 启用 serviceregistry 端点：查看、切换服务注册状态\n    serviceregistry:\n      enabled: true\n    # 启用 shutdown 端点：支持通过 HTTP 关闭应用\n    shutdown:\n      enabled: true\n    # 启用 Dubbo 端点：元数据总览\n    dubbo:\n      enabled: true\n    # 启用 dubbo-shutdown 端点：优雅停机状态\n    dubbo-shutdown:\n      enabled: true\n    # 启用 dubbo-configs 端点：Dubbo 配置\n    dubbo-configs:\n      enabled: true\n    # 启用 dubbo-services 端点：已发布的服务\n    dubbo-services:\n      enabled: true\n    # 启用 dubbo-references 端点：已引用的服务\n    dubbo-references:\n      enabled: true\n    # 启用 dubbo-properties 端点：Dubbo 配置属性\n    dubbo-properties:\n      enabled: true\n    # 健康端点配置\n    health:\n      # 健康详情全部展示（含各组件状态）\n      show-details: ALWAYS\n      # 启用 K8s 存活、就绪探针分组\n      probes.enabled: true\n  # 指标配置\n  metrics:\n    # 指标公共标签：应用、实例、环境\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    # 指标分布配置\n    distribution:\n      # HTTP 服务端请求指标开启直方图，支持百分位统计\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  # 观测（metrics、tracing）公共属性，与 metrics.tags 保持一致\n  observations:\n    key-values:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', 'c704d202c9b157bd86128f40ca93dadb', '2026-10-28 12:59:14', '2026-11-24 08:50:20', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8547, 'cloud-oauth.yml', 'DEFAULT_GROUP', '# 资源服务器 OAuth2：不透明令牌（Opaque Token）内省校验\nspring:\n  security:\n    oauth2:\n      resourceserver:\n        # 不透明令牌内省配置\n        opaquetoken:\n          # 内省调用方式（项目自定义键）：不配置或 rpc 走 Dubbo，其他值（如 http）走 Feign\n          # mode: http\n          # 以下两项为 Spring Security 默认内省器的属性；当前内省由自定义 OpaqueTokenIntrospector 完成，未被读取\n          client-id: system\n          client-secret: 123456', 'f925e2b395d0ec0f4ecac62de9317d38', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8548, 'boot-db.yml', 'DEFAULT_GROUP', '# 数据源与数据库访问配置：MySQL（HikariCP 连接池）、Flyway 建表迁移、MyBatis-Plus 及连表插件\nspring:\n  # 数据源配置（按生产环境 2C4G 规格调整）\n  datasource:\n    # 连接池实现类：HikariCP（Spring Boot 默认连接池）\n    type: com.zaxxer.hikari.HikariDataSource\n    # 驱动类未显式配置，由 Spring Boot 按 URL 自动推断（MySQL 8 为 com.mysql.cj.jdbc.Driver）\n    # JDBC 连接串，主机与库名支持环境变量覆盖，默认每服务一库（应用名-环境-db）\n    # 参数：useSSL=false 内网关闭 SSL；serverTimezone 指定时区；characterEncoding 指定编码（实际按 utf8mb4 建连）；\n    #       nullCatalogMeansCurrent=true 元数据查询时 catalog 传 null 视为当前库，避免扫出所有库\n    url: jdbc:mysql://${APPLICATION_MYSQL_SERVER:maozi-cloud-basic-mysql:3306}/${APPLICATION_MYSQL_SERVER_DB:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    # 数据库账号，通过环境变量注入\n    username: ${APPLICATION_MYSQL_SERVER_USERNAME:root}\n    # 数据库密码，通过环境变量注入\n    password: ${APPLICATION_MYSQL_SERVER_PASSWORD:password}\n    # Hikari 连接池配置\n    hikari:\n      # 连接事务隔离级别：2=READ_COMMITTED（读已提交）\n      transaction-isolation: 2\n      # 连接池名称，日志与监控指标按此区分应用\n      pool-name: ${spring.application.name}-HikariPool\n      # 最大连接数，2C4G 单 Pod 经验值 10~20，以压测结果为准\n      maximum-pool-size: 15\n      # 最小空闲连接数：与最大连接数相等即为固定大小连接池，避免流量波动时频繁建连\n      minimum-idle: 15\n      # 获取连接的超时时间，超时快速失败\n      connection-timeout: 3000\n      # 连接有效性校验超时，需小于 connection-timeout\n      validation-timeout: 2000\n      # 连接最大存活时间，需比 MySQL wait_timeout 小至少 60s，到期后异步关闭重建\n      max-lifetime: 540000\n      # 空闲连接保活探测间隔（最小 30s），防止连接被 K8s 网络或 MySQL 侧静默断开\n      keepalive-time: 30000\n      # 连接泄漏检测阈值：连接借出超过该时长未归还则打印告警堆栈\n      leak-detection-threshold: 60000\n      # 未配置 idle-timeout、connection-test-query：固定大小连接池不回收空闲连接，连接校验默认使用 JDBC4 isValid\n      # ---------- 驱动层调优（Connector/J 连接属性） ----------\n      data-source-properties:\n        # 开启客户端预编译语句缓存\n        cachePrepStmts: true\n        # 预编译语句缓存条数\n        prepStmtCacheSize: 250\n        # 可缓存的预编译 SQL 最大长度\n        prepStmtCacheSqlLimit: 2048\n        # 使用服务端预编译\n        useServerPrepStmts: true\n        # 会话状态（autocommit、隔离级别等）使用驱动本地缓存，减少与 MySQL 的往返\n        # 经代理（分库分表、读写分离）访问数据库时需关闭\n        useLocalSessionState: true\n        # autocommit 未变化时不再发送 SET autocommit\n        elideSetAutoCommits: true\n        # 缓存服务端配置，减少元数据往返\n        cacheServerConfiguration: true\n        # 缓存 ResultSet 元数据，减少元数据往返\n        cacheResultSetMetadata: true\n        # 不维护驱动内部计时统计，减少每次查询的系统时间调用\n        maintainTimeStats: false\n        # 批量语句改写：多条 INSERT 合并为多值语句，提升批量写入吞吐\n        # 注意：改写后批量返回的更新计数与自增主键可能与逐条执行不同，依赖这两者的代码需自测\n        rewriteBatchedStatements: true\n        # TCP 建连超时（毫秒），避免网络故障时长时间挂起\n        connectTimeout: 2000\n        # 网络读超时（毫秒），需大于最慢 SQL 的耗时\n        socketTimeout: 60000\n        # 开启 TCP KeepAlive，防止容器网络静默断连\n        tcpKeepAlive: true\n\n  # Flyway 数据库版本迁移：启动时按版本号执行 classpath:db 下的脚本\n  flyway:\n    # 启用 Flyway\n    enabled: true\n    # 迁移历史表名，记录已执行的脚本版本\n    table: system_table_flyway\n    # 禁用 clean 操作，防止误删库\n    clean-disabled: true\n    # 允许乱序执行，可补跑历史遗漏的脚本\n    out-of-order: true\n    # 对非空且无迁移历史表的库自动打基线，不从零执行\n    baseline-on-migrate: true\n    # 基线版本号\n    baseline-version: 0\n    # 迁移脚本目录\n    locations: classpath:db\n    # 迁移脚本编码\n    encoding: UTF-8\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  # Mapper XML 扫描路径，按项目缩写定位\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # 枚举包扫描；当前不生效：MP 3.5.6 自动装配未读取该属性，枚举处理见下方 default-enum-type-handler\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  # MyBatis 配置\n  configuration:\n    # 数据库列下划线命名自动映射到驼峰属性\n    map-underscore-to-camel-case: true\n    # SQL 日志实现：生产环境默认不配置；排查时可启用自定义封装 MybatisPlusLog，或直出控制台的 StdOutImpl\n    # log-impl: com.maozi.db.config.MybatisPlusLog\n    # 默认枚举类型处理器：MyBatis-Plus 通用枚举处理器\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  # MyBatis-Plus 全局配置\n  global-config:\n    # 当前不生效：MP 3.5.6 的 GlobalConfig 无 refresh 属性\n    refresh: false\n    # 关闭 MyBatis-Plus 启动 banner\n    banner: false\n    # 数据库相关全局配置\n    db-config:\n      # 当前不生效：MP 3.5.6 的 DbConfig 无 dbType 属性\n      db-type: mysql\n      # 主键策略：数据库自增\n      id-type: AUTO\n      # 当前不生效：MP 3.5.6 无 field-strategy 属性\n      # 已拆分为 insert-strategy、update-strategy、where-strategy（默认均为 NOT_NULL）\n      field-strategy: NOT_NULL\n      # 当前不生效：MP 3.5.6 的 DbConfig 无 columnLike 属性\n      column-like: false\n      # SQL 关键字大写输出\n      capital-mode: true\n      # 逻辑已删除值：1=已删除\n      logic-delete-value: 1\n      # 逻辑未删除值：0=未删除\n      logic-not-delete-value: 0\n\n# MyBatis-Plus-Join 连表查询插件配置\nmybatis-plus-join:\n  # 关闭插件启动 banner\n  banner: false\n  # 连表查询主表默认别名\n  table-alias: main', '0c5f9fe3d0d08eae5535f134fc4782b4', '2026-10-28 12:59:14', '2026-11-24 08:56:42', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8549, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '# 系统服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# 项目级免认证接口白名单（在系统默认白名单基础上追加），多个路径逗号分隔\napplication-project-whitelist: /config/system/get\n\n# 项目公开信息（/config/system/get 接口返回，供前端展示）\napplication-project-system:\n  # 项目名称\n  projectName: 小猫子脚手架\n  # 公司名称\n  corporationName: 小猫子网络科技有限公司\n  # 系统图标地址\n  icon: http://dummyimage.com/100x100\n  # 运行环境，复用全局环境标识\n  environment: ${application.environment}\n  # 项目描述\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  # 版权声明\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\n# 文件上传配置\nspring.servlet.multipart:\n  # 单个上传文件的大小上限\n  max-file-size: 1MB\n\n# 文件存储配置\noss:\n  # 存储类型：aliyun 表示路由到阿里云 OSS 处理器\n  store-type: aliyun\n  # 阿里云 OSS 配置\n  aliyun:\n    # 阿里云 AccessKey ID，从环境变量注入\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    # 阿里云 AccessKey Secret，从环境变量注入\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    # 地域\n    region: cn-beijing\n    # 访问域名\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    # 存储空间名称\n    bucket: maozi-cloud-bucket\n    #domain:    # 可选，CDN 自定义域名', 'f70f630ef9ecad4a89c15f440ffa112b', '2026-10-28 12:59:14', '2026-11-24 08:49:52', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8550, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '# 认证授权服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# 项目级免认证接口白名单（在系统默认白名单基础上追加），多个路径逗号分隔；当前未配置\n# application-project-whitelist:', '40d5ca65ec89a93bccb4f530e0b720ac', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8551, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '# 网关服务自身配置：端口、Sentinel 网关流控、路由转发\napplication:\n  # 对外统一入口端口（作为 cloud-default.yml 中 server.port 的默认值）\n  port: 1100\n  # 服务标题与描述\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\n# Sentinel 网关流控配置\nspring:\n  cloud:\n    sentinel:\n      # 自定义键（非 Sentinel 官方属性）：Sentinel 应用名，同时作为下方规则 dataId 的前缀\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 应用启动即连接控制台（默认首次请求时才注册）\n      eager: true\n      # 与控制台的通信配置\n      transport:\n        # 客户端与控制台通信的本地端口，被占用时自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 关闭通用 Web 流控过滤器，改由网关适配器（SentinelGatewayFilter）按路由、API 分组限流\n      filter:\n        enabled: false\n      # 规则数据源：规则存于 Nacos middleware 命名空间 SENTINEL_GROUP，变更后实时生效\n      # 各数据源通用字段：server-addr=Nacos 地址，namespace=命名空间，groupId=分组，\n      #                  dataId=规则文件名，rule-type=规则类型\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        # 网关流控规则（按路由或 API 分组限流）\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        # 网关 API 分组定义（将多个接口路径归为一组，供 gw-flow 引用）\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    # Spring Cloud Gateway 配置\n    gateway:\n      # 网关 HTTP 客户端配置\n      httpclient:\n        # 连接后端服务的超时时间（毫秒）\n        connect-timeout: 1000\n        # 等待后端响应的超时时间\n        response-timeout: 30s\n\n      # 服务发现路由配置\n      discovery:\n        locator:\n          # 按服务名自动创建路由（/服务名/** 转发到对应服务）\n          enabled: true\n\n      # 默认过滤器：对所有路由生效\n      default-filters:\n      # 去掉第一段路径前缀后再转发（/system/xxx → /xxx）\n      - StripPrefix=1\n      # 失败重试过滤器\n      - name: Retry\n        # 重试参数\n        args:\n          # 重试次数\n          retries: 1\n          # 按状态码系列重试：设为 INFORMATIONAL（1xx）即不按系列重试\n          series: INFORMATIONAL\n          # 仅 GET、POST 请求重试\n          methods:\n            - GET\n            - POST\n          # 命中以下后端状态码时重试：502、504、503\n          statuses:\n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          # 命中以下异常时重试：连接失败、未找到服务实例、连接被提前关闭\n          exceptions:\n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n      # 显式路由：路径前缀 → 注册中心服务（lb:// 表示负载均衡），新增服务照此添加\n      routes:\n        # 系统服务\n        - id: MAOZI-CLOUD-SYSTEM\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-system-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/system/**\n        # 认证服务\n        - id: MAOZI-CLOUD-OAUTH\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-oauth-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/oauth/**\n        # AI 服务\n        - id: MAOZI-CLOUD-AI-SERVICE\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-ai-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/ai/**', '317181f0d5c338887fcff96f25b8c6d4', '2026-10-28 12:59:14', '2026-11-24 08:54:45', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8552, 'cloud-seata.yml', 'DEFAULT_GROUP', '# Seata 分布式事务客户端配置\nseata:\n  # 启用 Seata 自动装配，@GlobalTransactional 才会生效\n  enabled: true\n  # Seata 应用标识，取服务名\n  application-id: ${spring.application.name}\n  # 事务分组（maozi-cloud-{环境}-tx-group），须与 seata.properties 中的 service.vgroupMapping 映射对应\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  # Seata 配置中心：从 Nacos middleware 命名空间 SEATA_GROUP 读取 seata.properties\n  config:\n    # 配置中心类型：Nacos\n    type: nacos\n    # Nacos 连接信息\n    nacos:\n      # Nacos 地址，复用配置中心地址\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      # 命名空间\n      namespace: middleware\n      # 分组\n      group: SEATA_GROUP\n      # 配置文件 dataId\n      dataId: seata.properties\n      # Nacos 访问账号\n      username: \'nacos\'\n      # Nacos 访问密码\n      password: \'nacos\'\n  # Seata 注册中心：按应用名 maozi-cloud-basic-seata 在 Nacos 中发现 TC 服务端\n  registry:\n    # 注册中心类型：Nacos\n    type: nacos\n    # Nacos 连接信息\n    nacos:\n      # TC 服务端注册到 Nacos 的应用名\n      application: maozi-cloud-basic-seata\n      # Nacos 地址，复用注册中心地址\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      # 命名空间\n      namespace: middleware\n      # 分组\n      group: SEATA_GROUP\n      # Nacos 访问账号\n      username: \'nacos\'\n      # Nacos 访问密码\n      password: \'nacos\'', '79de6eb2915b3d56521ac152560285fe', '2026-10-28 12:59:14', '2026-11-24 08:53:59', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8553, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '# AI 服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# Spring AI 模型接入：当前启用 DashScope（阿里云百炼），zhipuai、openai 为备选，切换时需同时引入对应 starter\nspring:\n  ai:\n    # 智谱 AI（备选，默认不启用）\n    # zhipuai:\n    #   base-url: https://api.z.ai/api/paas\n    #   api-key:\n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    # 阿里云百炼（DashScope）\n    dashscope:\n      # API Key，从环境变量注入，禁止写死在配置里\n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      # 对话模型配置\n      chat:\n        # 启用对话模型\n        enabled: true\n        # 模型参数\n        options:\n          # 文本对话模型\n          model: qwen-max\n          # 图生文模型（项目自定义键），对话携带图片时切换使用\n          text_image_model: qwen-vl-max\n      # 向量模型，默认关闭，知识库、RAG 场景再开启\n      embedding:\n        enabled: false\n        # 模型参数\n        options:\n          # 向量模型\n          model: text-embedding-v3\n          # 向量维度\n          dimensions: 1024\n    # OpenAI（备选，默认不启用）\n    # openai:\n    #   base-url:\n    #   api-key:\n    #   chat:\n    #     options:\n    #       model: gpt\n    #   embedding:\n    #     enabled: false', 'ecf3106617456bcb661e77bc6e796edd', '2026-10-28 12:59:14', '2026-11-24 08:49:52', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8554, 'boot-snailjob.yml', 'DEFAULT_GROUP', '# SnailJob 客户端配置（分布式任务调度、重试）\nsnail-job:\n  # SnailJob 服务端连接信息\n  server:\n    # 服务端地址（IP 或域名），集群时需前置负载均衡\n    host: ${APPLICATION_SNAIL_JOB_SERVER:maozi-cloud-basic-snailjob}\n    # 服务端通讯端口（非管理后台页面端口）\n    port: 17888\n  # 命名空间，须与服务端一致（此处直接使用环境名）\n  namespace: ${application.environment}\n  # 接入组名，须与服务端一致\n  group: ${spring.application.name}-${application.version:main}\n  # 接入组令牌，须与服务端一致\n  token: SJ_Wyz3dmsdbDOkDujOTSSoBjGQP1BMsVnj\n  # 客户端绑定 IP，服务端须可访问；不配置则自动获取，服务端无法调度客户端时再手动指定\n  # host: 127.0.0.1\n  # 客户端通讯端口\n  port: 17889\n  # 实例标签：携带版本号，可在控制台按版本筛选\n  labels:\n    version: ${application.version:main}', '980eaf03e83651def53ba015a5740e97', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8555, 'boot-xxljob.yml', 'DEFAULT_GROUP', '# XXL-Job 执行器配置（引入 maozi-cloud-config-xxljob 模块的服务生效）\nxxl:\n  job:\n    # 与调度中心一致的通讯令牌\n    accessToken: default_token\n    # 调度中心配置\n    admin:\n      # 调度中心地址，多个地址逗号分隔\n      addresses: http://${APPLICATION_XXLJOB_SERVER:maozi-cloud-basic-xxljob:12000}/xxljob\n    # 执行器配置\n    executor:\n      # 执行器AppName（应用名-环境-版本），调度中心按此注册执行器\n      appname: ${spring.application.name}-${application.environment}-${application.version}\n      # 当前不生效：项目 JobProperties 无对应字段，仅 ip 参与注册\n      address: \"\"\n      # 执行器 IP，留空则自动获取\n      ip: \"\"\n      # 执行器端口，小于等于 0 时自动获取可用端口\n      port: 0\n      # 执行器日志文件路径\n      logpath: ./data/xxl-job\n      # 执行器日志保留天数，小于 3 时不清理\n      logRetentionDays: 30', '8dd94cebdc9d6305036b56662264462e', '2026-10-28 12:59:14', '2026-11-24 08:49:24', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8556, 'maozi-cloud-basic-monitor.yml', 'DEFAULT_GROUP', '# 监控服务自身配置（Spring Boot Admin 服务端）\n# title/details：服务标题与描述\napplication:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\n# Spring Boot Admin 服务端配置，控制台访问地址 :2000/monitor\nspring:\n  boot:\n    admin:\n      # 控制台上下文路径（nginx 将 /monitor/ 原样透传）\n      context-path: /monitor\n      # 服务发现配置\n      discovery:\n        # 关闭通过服务发现自动注册，改为客户端主动注册\n        enabled: false\n  # 控制台登录账号，同时作为客户端注册（见 boot-monitor.yml）所用的账号密码\n  security:\n    user:\n      name: monitor\n      password: monitor\n\n# Actuator 端点基础路径，与控制台同挂在 /monitor 下\nmanagement:\n  endpoints:\n    web:\n      base-path: /monitor/actuator', 'e9e024e848e5bbdb49b5d5af1cfc3a57', '2026-10-28 12:59:14', '2026-11-24 08:53:59', NULL, '192.168.65.1', '', 'prod', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8559, 'boot-redis.yml', 'DEFAULT_GROUP', '# Redis 连接配置（Spring Data Redis + Lettuce 连接池），地址、密码等均支持环境变量覆盖\nspring:\n  data:\n    redis:\n      # Redis 地址，默认指向容器内基础 Redis\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      # Redis 端口\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # Redis 密码，从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      # 逻辑库编号（0~15），按环境或业务隔离数据\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 客户端标识，便于通过 redis client list 排查\n      client-name: ${spring.application.name}-${application.environment}-${application.version}\n      # Lettuce 客户端配置\n      lettuce:\n        # 当前不生效：lettuce 下无 timeout 属性，命令超时应配置在 spring.data.redis.timeout（现为 Lettuce 默认 60s）\n        timeout: 500ms\n        # 应用关闭时等待在途命令执行完的超时时间\n        shutdown-timeout: 300ms\n        # 连接池配置\n        pool:\n          # 连接池最大连接数，按单实例 QPS 调整\n          max-active: 120\n          # 获取连接的最大等待时间，超时则抛出异常\n          max-wait: 1000ms\n          # 最大空闲连接数\n          max-idle: 60\n          # 最小空闲连接数（预热连接）\n          min-idle: 10', '48128ea6a5cbfec6a67615e91b86611e', '2026-10-28 13:18:29', '2026-11-24 08:48:43', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8560, 'cloud-default.yml', 'DEFAULT_GROUP', '# 所有服务共用的基础配置：Web 容器、优雅停机、MVC、JSON 序列化、Feign、日志级别（服务自身 yml 可覆盖）\n# Web 容器配置\nserver:\n  # 服务端口，优先级：环境变量 APPLICATION_PORT > application.port > 0（随机端口）\n  port: ${APPLICATION_PORT:${application.port:0}}\n  # 统一错误处理路径（落在免认证白名单 /application/** 内）\n  error.path: /application/error\n  # 优雅停机：graceful=等待在途请求处理完再关闭 / immediate=立即关闭\n  shutdown: graceful\n\n# Spring 通用配置\nspring:\n  # 生命周期配置\n  lifecycle:\n    # 优雅停机每个阶段的最长等待时间\n    timeout-per-shutdown-phase: 65s\n  # 启动配置\n  main:\n    # 关闭启动 banner，保持控制台干净\n    banner-mode: off\n    # 关闭启动信息日志（由 BaseApplication 统一输出）\n    log-startup-info: false\n  # Web 配置\n  web:\n    # 静态资源映射\n    resources:\n      # 不映射静态资源，纯接口服务\n      add-mappings: false\n  # Spring MVC 配置\n  mvc:\n    # 未匹配到处理器时抛出 NoHandlerFoundException，交给全局异常处理器返回 404\n    throw-exception-if-no-handler-found: true\n    # 路径匹配策略使用 AntPathMatcher（默认为 PathPatternParser）\n    pathmatch.matching-strategy: ant_path_matcher\n  # Jackson 序列化配置\n  jackson:\n    # 时区\n    time-zone: GMT+8\n    # 日期格式\n    date-format: yyyy-MM-dd HH:mm:ss\n    # null 字段不参与序列化\n    default-property-inclusion: NON_NULL\n\n# Feign 远程调用配置\nfeign:\n  # Feign 接口接入 Sentinel 熔断降级\n  sentinel:\n    enabled: true\n\n  # 以下四组为 OpenFeign 3.x 旧前缀属性，4.x 已改为 spring.cloud.openfeign.*，当前均不生效\n  # okhttp.enabled 对应 spring.cloud.openfeign.okhttp.enabled（启用 OkHttp 作为底层 HTTP 客户端）\n  okhttp:\n    enabled: true\n  # httpclient.enabled 对应 spring.cloud.openfeign.httpclient.hc5.enabled（默认关闭）\n  httpclient:\n    enabled: false\n  # client.config 对应 spring.cloud.openfeign.client.config（connect-timeout、read-timeout）\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  # compression 对应 spring.cloud.openfeign.compression（请求、响应压缩）\n  compression:\n    # 请求压缩\n    request:\n      enabled: true\n      min-request-size: 1024\n      mime-types: text/xml,application/xml,application/json\n    # 响应压缩\n    response:\n      enabled: true\n\n# 日志级别配置\nlogging:\n  # 各包日志级别\n  level:\n    # 根日志级别：仅输出错误\n    root: ERROR\n    # 项目代码日志级别\n    com.maozi: INFO\n    # Dubbo 注册日志关闭\n    org.apache.dubbo.registry: OFF\n    # Dubbo 通信日志关闭\n    org.apache.dubbo.remoting: OFF', '64d5a88b2143a07e60dc654c003a5dac', '2026-10-28 13:18:29', '2026-11-24 08:48:43', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8561, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '# Dubbo RPC 配置\ndubbo:\n  # Dubbo 应用配置\n  application:\n    # Dubbo 应用名（前缀 dubbo- + 服务名）\n    name: dubbo-${spring.application.name}\n    # 注册模式：instance=应用级服务发现 / interface=接口级 / all=双注册（会增加注册中心压力）\n    register-mode: instance\n    # 应用版本（随 application.version），用于版本路由与灰度\n    version: ${application.version:main}\n    # 关闭序列化安全检查，避免自定义实体校验报错（仅限内网环境，端口暴露到外部时必须开启）\n    serialize-check-status: DISABLE\n    # 不校验序列化类是否实现 Serializable\n    check-serializable: false\n  # RPC 实现类扫描包，按项目缩写拼接（如 system → com.maozi.system.*.api.impl.rpc）\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  # 通信协议配置\n  protocol:\n    # 通信协议：dubbo；需要 Triple/gRPC 时改为 tri\n    name: dubbo\n    # Dubbo 端口，-1 表示随机；固定端口用 APPLICATION_DUBBO_PORT 或 application.dubbo.port 指定\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  # 服务提供者配置\n  provider:\n    # 默认超时时间（毫秒）：30000 即 30s，联调环境容忍慢接口\n    timeout: 30000\n    # 自定义过滤器：服务端从 RPC 附件还原用户、链路等上下文\n    filter: applicationDubboContextLoadFilter\n    # 优先使用的序列化方式\n    prefer-serialization: hessian2\n    # 序列化方式\n    serialization: hessian2\n  # 服务消费者配置\n  consumer:\n    # 启动时不检查依赖的服务是否在线，解除服务启动顺序耦合\n    check: false\n    # 默认超时时间（毫秒），30s\n    timeout: 30000\n    # 失败后自动重试 1 次，非幂等接口需在 @DubboReference 上单独关闭\n    retries: 1\n    # 自定义过滤器：消费端将用户、链路等上下文写入 RPC 附件透传\n    filter: applicationDubboContextTransmitFilter\n  # 注册中心：复用 Nacos（与配置中心同实例），namespace 随环境隔离\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', 'ced6b34ee1211a1a8988527017a0430a', '2026-10-28 13:18:29', '2026-11-24 08:55:11', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8562, 'cloud-nacos.yml', 'DEFAULT_GROUP', '# Nacos 服务发现配置（server-addr、namespace 由启动初始化器按环境写入）\nspring:\n  cloud:\n    nacos:\n      # 服务发现配置\n      discovery:\n        # 启用 Nacos 服务发现\n        enabled: true\n        # 启动时将本实例注册到注册中心\n        register-enabled: true\n        # 实例元数据：携带版本号，灰度路由按此筛选实例\n        metadata:\n          version: ${application.version:main}', 'fe9dc2a75e748eeb2a23b3f914658e4d', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8563, 'cloud-rocket.yml', 'DEFAULT_GROUP', '# RocketMQ 配置（当前未启用：无服务引入 stream 模块，接入 MQ 时替换 name-server）\nspring:\n  cloud:\n    stream:\n      rocketmq:\n        # RocketMQ Binder 配置\n        binder:\n          # access-key:    # 阿里云 AccessKey ID，按需配置\n          # secret-key:    # 阿里云 AccessKey Secret，按需配置\n          # NameServer 地址\n          name-server: localhost:9876\n# 以下为预留占位，未启用\n# rocketmq:\n  # instance:\n    # id:\n    # name:', '7ed1c9e411ede71a7a001c6cfa0fa149', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8564, 'cloud-sentinel.yml', 'DEFAULT_GROUP', '# Sentinel 流量防护配置（业务服务共用，网关见 maozi-cloud-gateway-service.yml）\n\n# RestTemplate 纳入 Sentinel 熔断限流（默认已开启）\nresttemplate:\n  sentinel:\n    enabled: true\n\n# Feign 接口接入 Sentinel 熔断降级\nfeign:\n  sentinel:\n    enabled: true\n\n# Sentinel 客户端：控制台接入、规则从 Nacos 加载\nspring:\n  cloud:\n    sentinel:\n      # 自定义键（非 Sentinel 官方属性）：Sentinel 应用名，同时作为下方规则 dataId 的前缀\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 应用启动即连接控制台（默认首次请求时才注册）\n      eager: true\n      # 与控制台的通信配置\n      transport:\n        # 客户端与控制台通信的本地端口，被占用时自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 资源名带 HTTP 方法前缀（如 GET:/user/info），区分同路径的不同请求方法\n      http-method-specify: true\n      # 规则数据源：规则存于 Nacos middleware 命名空间 SENTINEL_GROUP，变更后实时生效\n      # 各数据源通用字段：server-addr=Nacos 地址，namespace=命名空间，groupId=分组，\n      #                  dataId=规则文件名，rule-type=规则类型\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', 'e089fa4e387e2e024d989e306ec67830', '2026-10-28 13:18:29', '2026-11-24 08:47:55', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8565, 'boot-lock.yml', 'DEFAULT_GROUP', '# 分布式锁配置（Redisson 客户端连接、锁默认超时）\nlock:\n  # Redisson 配置\n  redisson:\n    # 单节点 Redis 地址，复用 spring.data.redis 的地址与端口\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    # Redis 密码\n    password: ${spring.data.redis.password}\n    # Redis 逻辑库编号\n    database: ${spring.data.redis.database:0}\n    # 集群模式：配置节点地址列表后自动启用，与 address 二选一\n    # node-addresses: redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # 获取锁的最长等待时间（秒），不配置默认 60\n    # waitTime: 60\n    # 锁的自动释放时间（秒），不配置默认 60\n    # leaseTime: 60', '3dd8b897d00f0f855638675d348e8b97', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8566, 'boot-monitor.yml', 'DEFAULT_GROUP', '# 监控配置：Spring Boot Admin 客户端注册、Actuator 端点与指标\nspring:\n  boot:\n    admin:\n      # Spring Boot Admin 客户端配置\n      client:\n        # SBA 服务端地址，启动后自动注册\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}/monitor\n        # 注册到 SBA 服务端所用的账号，须与服务端 spring.security.user 一致\n        username: monitor\n        password: monitor\n        # 应用关闭时自动从 SBA 服务端注销\n        auto-deregistration: true\n        # 注册实例信息\n        instance:\n          # 注册地址优先使用 IP（项目已固定取 spring.cloud.client.ip-address，此项仅作兜底）\n          prefer-ip: true\n          # 实例元数据：SBA 控制台展示的环境与版本\n          metadata:\n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            # 实例标签：环境、版本，可用于控制台筛选\n            tags:\n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\n# 当前不生效：endpoints.<id>.enabled 为 Boot 2.x 旧属性，Dubbo 端点由下方 management.endpoint.dubbo.enabled 控制\nendpoints:\n  dubbo:\n    enabled: true\n\n# Actuator 端点与指标\nmanagement:\n  # info 端点展示 info.* 配置项\n  info.env.enabled: true\n  # Dubbo 健康检查配置\n  health:\n    dubbo:\n      status:\n        # Dubbo 健康检查默认项：内存\n        defaults: memory\n        # 附加检查项：系统负载、线程池\n        extras: load,threadpool\n  # Web 端点暴露配置\n  endpoints:\n    web:\n      exposure:\n        # 暴露全部 Web 端点\n        include: \'*\'\n  # 各端点开关配置\n  endpoint:\n    # env 端点展示配置项的值\n    env.show-values: always\n    # 启用 serviceregistry 端点：查看、切换服务注册状态\n    serviceregistry:\n      enabled: true\n    # 启用 shutdown 端点：支持通过 HTTP 关闭应用\n    shutdown:\n      enabled: true\n    # 启用 Dubbo 端点：元数据总览\n    dubbo:\n      enabled: true\n    # 启用 dubbo-shutdown 端点：优雅停机状态\n    dubbo-shutdown:\n      enabled: true\n    # 启用 dubbo-configs 端点：Dubbo 配置\n    dubbo-configs:\n      enabled: true\n    # 启用 dubbo-services 端点：已发布的服务\n    dubbo-services:\n      enabled: true\n    # 启用 dubbo-references 端点：已引用的服务\n    dubbo-references:\n      enabled: true\n    # 启用 dubbo-properties 端点：Dubbo 配置属性\n    dubbo-properties:\n      enabled: true\n    # 健康端点配置\n    health:\n      # 健康详情全部展示（含各组件状态）\n      show-details: ALWAYS\n      # 启用 K8s 存活、就绪探针分组\n      probes.enabled: true\n  # 指标配置\n  metrics:\n    # 指标公共标签：应用、实例、环境\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    # 指标分布配置\n    distribution:\n      # HTTP 服务端请求指标开启直方图，支持百分位统计\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  # 观测（metrics、tracing）公共属性，与 metrics.tags 保持一致\n  observations:\n    key-values:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', 'c704d202c9b157bd86128f40ca93dadb', '2026-10-28 13:18:29', '2026-11-24 08:47:55', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8567, 'cloud-oauth.yml', 'DEFAULT_GROUP', '# 资源服务器 OAuth2：不透明令牌（Opaque Token）内省校验\nspring:\n  security:\n    oauth2:\n      resourceserver:\n        # 不透明令牌内省配置\n        opaquetoken:\n          # 内省调用方式（项目自定义键）：不配置或 rpc 走 Dubbo，其他值（如 http）走 Feign\n          # mode: http\n          # 以下两项为 Spring Security 默认内省器的属性；当前内省由自定义 OpaqueTokenIntrospector 完成，未被读取\n          client-id: system\n          client-secret: 123456', 'f925e2b395d0ec0f4ecac62de9317d38', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8568, 'boot-db.yml', 'DEFAULT_GROUP', '# 数据源与数据库访问配置：MySQL（HikariCP 连接池）、Flyway 建表迁移、MyBatis-Plus 及连表插件\nspring:\n  # 数据源配置\n  datasource:\n    # 连接池实现类：HikariCP（Spring Boot 默认连接池）\n    type: com.zaxxer.hikari.HikariDataSource\n    # MySQL 8 驱动类\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    # JDBC 连接串，主机与库名支持环境变量覆盖，默认每服务一库（应用名-环境-db）\n    # 参数：useSSL=false 内网关闭 SSL；serverTimezone 指定时区；characterEncoding 指定编码；\n    #       nullCatalogMeansCurrent=true 元数据查询时 catalog 传 null 视为当前库，避免扫出所有库\n    url: jdbc:mysql://${APPLICATION_MYSQL_SERVER:maozi-cloud-basic-mysql:3306}/${APPLICATION_MYSQL_SERVER_DB:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    # 数据库账号，默认值仅供本地，其他环境通过环境变量覆盖\n    username: ${APPLICATION_MYSQL_SERVER_USERNAME:root}\n    # 数据库密码，默认值仅供本地，其他环境通过环境变量覆盖\n    password: ${APPLICATION_MYSQL_SERVER_PASSWORD:password}\n    # Hikari 连接池配置\n    hikari:\n      # 连接事务隔离级别：2=READ_COMMITTED（读已提交）\n      transaction-isolation: 2\n      # 最大连接数，按业务压测调整\n      maximum-pool-size: 15\n      # 获取连接的超时时间，超时抛出异常快速失败\n      connection-timeout: 6000\n      # 空闲连接回收超时；当前不生效：未配置 minimum-idle 时为固定大小连接池，HikariCP 忽略该项\n      idle-timeout: 300000\n      # 连接最大存活时间，需比 MySQL wait_timeout 小至少 60s，到期后异步关闭重建\n      max-lifetime: 540000\n\n  # Flyway 数据库版本迁移：启动时按版本号执行 classpath:db 下的脚本\n  flyway:\n    # 启用 Flyway\n    enabled: true\n    # 迁移历史表名，记录已执行的脚本版本\n    table: system_table_flyway\n    # 禁用 clean 操作，防止误删库\n    clean-disabled: true\n    # 允许乱序执行，可补跑历史遗漏的脚本\n    out-of-order: true\n    # 对非空且无迁移历史表的库自动打基线，不从零执行\n    baseline-on-migrate: true\n    # 基线版本号\n    baseline-version: 0\n    # 迁移脚本目录\n    locations: classpath:db\n    # 迁移脚本编码\n    encoding: UTF-8\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  # Mapper XML 扫描路径，按项目缩写定位\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # 枚举包扫描；当前不生效：MP 3.5.6 自动装配未读取该属性，枚举处理见下方 default-enum-type-handler\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  # MyBatis 配置\n  configuration:\n    # 数据库列下划线命名自动映射到驼峰属性\n    map-underscore-to-camel-case: true\n    # SQL 日志实现：自定义封装；需要直接输出到控制台时改用下方 StdOutImpl\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    # 默认枚举类型处理器：MyBatis-Plus 通用枚举处理器\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  # MyBatis-Plus 全局配置\n  global-config:\n    # 当前不生效：MP 3.5.6 的 GlobalConfig 无 refresh 属性\n    refresh: false\n    # 关闭 MyBatis-Plus 启动 banner\n    banner: false\n    # 数据库相关全局配置\n    db-config:\n      # 当前不生效：MP 3.5.6 的 DbConfig 无 dbType 属性\n      db-type: mysql\n      # 主键策略：数据库自增\n      id-type: AUTO\n      # 当前不生效：MP 3.5.6 无 field-strategy 属性\n      # 已拆分为 insert-strategy、update-strategy、where-strategy（默认均为 NOT_NULL）\n      field-strategy: NOT_NULL\n      # 当前不生效：MP 3.5.6 的 DbConfig 无 columnLike 属性\n      column-like: false\n      # SQL 关键字大写输出\n      capital-mode: true\n      # 逻辑已删除值：1=已删除\n      logic-delete-value: 1\n      # 逻辑未删除值：0=未删除\n      logic-not-delete-value: 0\n\n# MyBatis-Plus-Join 连表查询插件配置\nmybatis-plus-join:\n  # 关闭插件启动 banner\n  banner: false\n  # 连表查询主表默认别名\n  table-alias: main', 'eb997e6806173760051a1efe8f0f5dfe', '2026-10-28 13:18:29', '2026-11-24 08:48:43', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8569, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '# 系统服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# 项目级免认证接口白名单（在系统默认白名单基础上追加），多个路径逗号分隔\napplication-project-whitelist: /config/system/get\n\n# 项目公开信息（/config/system/get 接口返回，供前端展示）\napplication-project-system:\n  # 项目名称\n  projectName: 小猫子脚手架\n  # 公司名称\n  corporationName: 小猫子网络科技有限公司\n  # 系统图标地址\n  icon: http://dummyimage.com/100x100\n  # 运行环境，复用全局环境标识\n  environment: ${application.environment}\n  # 项目描述\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  # 版权声明\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\n# 文件上传配置\nspring.servlet.multipart:\n  # 单个上传文件的大小上限\n  max-file-size: 1MB\n\n# 文件存储配置\noss:\n  # 存储类型：aliyun 表示路由到阿里云 OSS 处理器\n  store-type: aliyun\n  # 阿里云 OSS 配置\n  aliyun:\n    # 阿里云 AccessKey ID，从环境变量注入\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    # 阿里云 AccessKey Secret，从环境变量注入\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    # 地域\n    region: cn-beijing\n    # 访问域名\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    # 存储空间名称\n    bucket: maozi-cloud-bucket\n    #domain:    # 可选，CDN 自定义域名', 'f70f630ef9ecad4a89c15f440ffa112b', '2026-10-28 13:18:29', '2026-11-24 08:47:55', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8570, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '# 认证授权服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# 项目级免认证接口白名单（在系统默认白名单基础上追加），多个路径逗号分隔；当前未配置\n# application-project-whitelist:', '40d5ca65ec89a93bccb4f530e0b720ac', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8571, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '# 网关服务自身配置：端口、Sentinel 网关流控、路由转发\napplication:\n  # 对外统一入口端口（作为 cloud-default.yml 中 server.port 的默认值）\n  port: 1100\n  # 服务标题与描述\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\n# Sentinel 网关流控配置\nspring:\n  cloud:\n    sentinel:\n      # 自定义键（非 Sentinel 官方属性）：Sentinel 应用名，同时作为下方规则 dataId 的前缀\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 应用启动即连接控制台（默认首次请求时才注册）\n      eager: true\n      # 与控制台的通信配置\n      transport:\n        # 客户端与控制台通信的本地端口，被占用时自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 关闭通用 Web 流控过滤器，改由网关适配器（SentinelGatewayFilter）按路由、API 分组限流\n      filter:\n        enabled: false\n      # 规则数据源：规则存于 Nacos middleware 命名空间 SENTINEL_GROUP，变更后实时生效\n      # 各数据源通用字段：server-addr=Nacos 地址，namespace=命名空间，groupId=分组，\n      #                  dataId=规则文件名，rule-type=规则类型\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        # 网关流控规则（按路由或 API 分组限流）\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        # 网关 API 分组定义（将多个接口路径归为一组，供 gw-flow 引用）\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    # Spring Cloud Gateway 配置\n    gateway:\n      # 网关 HTTP 客户端配置\n      httpclient:\n        # 连接后端服务的超时时间（毫秒）\n        connect-timeout: 1000\n        # 等待后端响应的超时时间\n        response-timeout: 30s\n\n      # 服务发现路由配置\n      discovery:\n        locator:\n          # 按服务名自动创建路由（/服务名/** 转发到对应服务）\n          enabled: true\n\n      # 默认过滤器：对所有路由生效\n      default-filters:\n      # 去掉第一段路径前缀后再转发（/system/xxx → /xxx）\n      - StripPrefix=1\n      # 失败重试过滤器\n      - name: Retry\n        # 重试参数\n        args:\n          # 重试次数\n          retries: 1\n          # 按状态码系列重试：设为 INFORMATIONAL（1xx）即不按系列重试\n          series: INFORMATIONAL\n          # 仅 GET、POST 请求重试\n          methods:\n            - GET\n            - POST\n          # 命中以下后端状态码时重试：502、504、503\n          statuses:\n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          # 命中以下异常时重试：连接失败、未找到服务实例、连接被提前关闭\n          exceptions:\n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n      # 显式路由：路径前缀 → 注册中心服务（lb:// 表示负载均衡），新增服务照此添加\n      routes:\n        # 系统服务\n        - id: MAOZI-CLOUD-SYSTEM\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-system-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/system/**\n        # 认证服务\n        - id: MAOZI-CLOUD-OAUTH\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-oauth-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/oauth/**\n        # AI 服务\n        - id: MAOZI-CLOUD-AI-SERVICE\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-ai-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/ai/**', '317181f0d5c338887fcff96f25b8c6d4', '2026-10-28 13:18:29', '2026-11-24 08:54:45', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8572, 'cloud-seata.yml', 'DEFAULT_GROUP', '# Seata 分布式事务客户端配置\nseata:\n  # 启用 Seata 自动装配，@GlobalTransactional 才会生效\n  enabled: true\n  # Seata 应用标识，取服务名\n  application-id: ${spring.application.name}\n  # 事务分组（maozi-cloud-{环境}-tx-group），须与 seata.properties 中的 service.vgroupMapping 映射对应\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  # Seata 配置中心：从 Nacos middleware 命名空间 SEATA_GROUP 读取 seata.properties\n  config:\n    # 配置中心类型：Nacos\n    type: nacos\n    # Nacos 连接信息\n    nacos:\n      # Nacos 地址，复用配置中心地址\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      # 命名空间\n      namespace: middleware\n      # 分组\n      group: SEATA_GROUP\n      # 配置文件 dataId\n      dataId: seata.properties\n      # Nacos 访问账号\n      username: \'nacos\'\n      # Nacos 访问密码\n      password: \'nacos\'\n  # Seata 注册中心：按应用名 maozi-cloud-basic-seata 在 Nacos 中发现 TC 服务端\n  registry:\n    # 注册中心类型：Nacos\n    type: nacos\n    # Nacos 连接信息\n    nacos:\n      # TC 服务端注册到 Nacos 的应用名\n      application: maozi-cloud-basic-seata\n      # Nacos 地址，复用注册中心地址\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      # 命名空间\n      namespace: middleware\n      # 分组\n      group: SEATA_GROUP\n      # Nacos 访问账号\n      username: \'nacos\'\n      # Nacos 访问密码\n      password: \'nacos\'', '79de6eb2915b3d56521ac152560285fe', '2026-10-28 13:18:29', '2026-11-24 08:53:59', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8573, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '# AI 服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# Spring AI 模型接入：当前启用 DashScope（阿里云百炼），zhipuai、openai 为备选，切换时需同时引入对应 starter\nspring:\n  ai:\n    # 智谱 AI（备选，默认不启用）\n    # zhipuai:\n    #   base-url: https://api.z.ai/api/paas\n    #   api-key:\n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    # 阿里云百炼（DashScope）\n    dashscope:\n      # API Key，从环境变量注入，禁止写死在配置里\n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      # 对话模型配置\n      chat:\n        # 启用对话模型\n        enabled: true\n        # 模型参数\n        options:\n          # 文本对话模型\n          model: qwen-max\n          # 图生文模型（项目自定义键），对话携带图片时切换使用\n          text_image_model: qwen-vl-max\n      # 向量模型，默认关闭，知识库、RAG 场景再开启\n      embedding:\n        enabled: false\n        # 模型参数\n        options:\n          # 向量模型\n          model: text-embedding-v3\n          # 向量维度\n          dimensions: 1024\n    # OpenAI（备选，默认不启用）\n    # openai:\n    #   base-url:\n    #   api-key:\n    #   chat:\n    #     options:\n    #       model: gpt\n    #   embedding:\n    #     enabled: false', 'ecf3106617456bcb661e77bc6e796edd', '2026-10-28 13:18:29', '2026-11-24 08:47:55', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8574, 'boot-snailjob.yml', 'DEFAULT_GROUP', '# SnailJob 客户端配置（分布式任务调度、重试）\nsnail-job:\n  # SnailJob 服务端连接信息\n  server:\n    # 服务端地址（IP 或域名），集群时需前置负载均衡\n    host: ${APPLICATION_SNAIL_JOB_SERVER:maozi-cloud-basic-snailjob}\n    # 服务端通讯端口（非管理后台页面端口）\n    port: 17888\n  # 命名空间，须与服务端一致（此处直接使用环境名）\n  namespace: ${application.environment}\n  # 接入组名，须与服务端一致\n  group: ${spring.application.name}-${application.version:main}\n  # 接入组令牌，须与服务端一致\n  token: SJ_Wyz3dmsdbDOkDujOTSSoBjGQP1BMsVnj\n  # 客户端绑定 IP，服务端须可访问；不配置则自动获取，服务端无法调度客户端时再手动指定\n  # host: 127.0.0.1\n  # 客户端通讯端口\n  port: 17889\n  # 实例标签：携带版本号，可在控制台按版本筛选\n  labels:\n    version: ${application.version:main}', '980eaf03e83651def53ba015a5740e97', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8575, 'boot-xxljob.yml', 'DEFAULT_GROUP', '# XXL-Job 执行器配置（引入 maozi-cloud-config-xxljob 模块的服务生效）\nxxl:\n  job:\n    # 与调度中心一致的通讯令牌\n    accessToken: default_token\n    # 调度中心配置\n    admin:\n      # 调度中心地址，多个地址逗号分隔\n      addresses: http://${APPLICATION_XXLJOB_SERVER:maozi-cloud-basic-xxljob:12000}/xxljob\n    # 执行器配置\n    executor:\n      # 执行器AppName（应用名-环境-版本），调度中心按此注册执行器\n      appname: ${spring.application.name}-${application.environment}-${application.version}\n      # 当前不生效：项目 JobProperties 无对应字段，仅 ip 参与注册\n      address: \"\"\n      # 执行器 IP，留空则自动获取\n      ip: \"\"\n      # 执行器端口，小于等于 0 时自动获取可用端口\n      port: 0\n      # 执行器日志文件路径\n      logpath: ./data/xxl-job\n      # 执行器日志保留天数，小于 3 时不清理\n      logRetentionDays: 30', '8dd94cebdc9d6305036b56662264462e', '2026-10-28 13:18:29', '2026-11-24 08:47:15', NULL, '192.168.65.1', '', 'dev', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8579, 'boot-redis.yml', 'DEFAULT_GROUP', '# Redis 连接配置（Spring Data Redis + Lettuce 连接池），地址、密码等均支持环境变量覆盖\nspring:\n  data:\n    redis:\n      # Redis 地址，默认指向容器内基础 Redis\n      host: ${APPLICATION_REDIS_SERVER:maozi-cloud-basic-redis}\n      # Redis 端口\n      port: ${APPLICATION_REDIS_PORT:6379}\n      # Redis 密码，从环境变量读取，禁止硬编码\n      password: ${APPLICATION_REDIS_SERVER_PASSWORD:password}\n      # 逻辑库编号（0~15），按环境或业务隔离数据\n      database: ${APPLICATION_REDIS_SERVER_DATABASE:0}\n      # 客户端标识，便于通过 redis client list 排查\n      client-name: ${spring.application.name}-${application.environment}-${application.version}\n      # Lettuce 客户端配置\n      lettuce:\n        # 当前不生效：lettuce 下无 timeout 属性，命令超时应配置在 spring.data.redis.timeout（现为 Lettuce 默认 60s）\n        timeout: 500ms\n        # 应用关闭时等待在途命令执行完的超时时间\n        shutdown-timeout: 300ms\n        # 连接池配置\n        pool:\n          # 连接池最大连接数，按单实例 QPS 调整\n          max-active: 120\n          # 获取连接的最大等待时间，超时则抛出异常\n          max-wait: 1000ms\n          # 最大空闲连接数\n          max-idle: 60\n          # 最小空闲连接数（预热连接）\n          min-idle: 10', '48128ea6a5cbfec6a67615e91b86611e', '2026-10-28 13:18:35', '2026-11-24 08:46:06', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8580, 'cloud-default.yml', 'DEFAULT_GROUP', '# 所有服务共用的基础配置：Web 容器、优雅停机、MVC、JSON 序列化、Feign、日志级别（服务自身 yml 可覆盖）\n# Web 容器配置\nserver:\n  # 服务端口，优先级：环境变量 APPLICATION_PORT > application.port > 0（随机端口）\n  port: ${APPLICATION_PORT:${application.port:0}}\n  # 统一错误处理路径（落在免认证白名单 /application/** 内）\n  error.path: /application/error\n  # 优雅停机：graceful=等待在途请求处理完再关闭 / immediate=立即关闭\n  shutdown: graceful\n\n# Spring 通用配置\nspring:\n  # 生命周期配置\n  lifecycle:\n    # 优雅停机每个阶段的最长等待时间\n    timeout-per-shutdown-phase: 65s\n  # 启动配置\n  main:\n    # 关闭启动 banner，保持控制台干净\n    banner-mode: off\n    # 关闭启动信息日志（由 BaseApplication 统一输出）\n    log-startup-info: false\n  # Web 配置\n  web:\n    # 静态资源映射\n    resources:\n      # 不映射静态资源，纯接口服务\n      add-mappings: false\n  # Spring MVC 配置\n  mvc:\n    # 未匹配到处理器时抛出 NoHandlerFoundException，交给全局异常处理器返回 404\n    throw-exception-if-no-handler-found: true\n    # 路径匹配策略使用 AntPathMatcher（默认为 PathPatternParser）\n    pathmatch.matching-strategy: ant_path_matcher\n  # Jackson 序列化配置\n  jackson:\n    # 时区\n    time-zone: GMT+8\n    # 日期格式\n    date-format: yyyy-MM-dd HH:mm:ss\n    # null 字段不参与序列化\n    default-property-inclusion: NON_NULL\n\n# Feign 远程调用配置\nfeign:\n  # Feign 接口接入 Sentinel 熔断降级\n  sentinel:\n    enabled: true\n\n  # 以下四组为 OpenFeign 3.x 旧前缀属性，4.x 已改为 spring.cloud.openfeign.*，当前均不生效\n  # okhttp.enabled 对应 spring.cloud.openfeign.okhttp.enabled（启用 OkHttp 作为底层 HTTP 客户端）\n  okhttp:\n    enabled: true\n  # httpclient.enabled 对应 spring.cloud.openfeign.httpclient.hc5.enabled（默认关闭）\n  httpclient:\n    enabled: false\n  # client.config 对应 spring.cloud.openfeign.client.config（connect-timeout、read-timeout）\n  client:\n    config:\n      default:\n        connectTimeout: 30000\n        readTimeout: 30000\n  # compression 对应 spring.cloud.openfeign.compression（请求、响应压缩）\n  compression:\n    # 请求压缩\n    request:\n      enabled: true\n      min-request-size: 1024\n      mime-types: text/xml,application/xml,application/json\n    # 响应压缩\n    response:\n      enabled: true\n\n# 日志级别配置\nlogging:\n  # 各包日志级别\n  level:\n    # 根日志级别：仅输出错误\n    root: ERROR\n    # 项目代码日志级别\n    com.maozi: INFO\n    # Dubbo 注册日志关闭\n    org.apache.dubbo.registry: OFF\n    # Dubbo 通信日志关闭\n    org.apache.dubbo.remoting: OFF', '64d5a88b2143a07e60dc654c003a5dac', '2026-10-28 13:18:35', '2026-11-24 08:46:38', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8581, 'cloud-dubbo.yml', 'DEFAULT_GROUP', '# Dubbo RPC 配置\ndubbo:\n  # Dubbo 应用配置\n  application:\n    # Dubbo 应用名（前缀 dubbo- + 服务名）\n    name: dubbo-${spring.application.name}\n    # 注册模式：instance=应用级服务发现 / interface=接口级 / all=双注册（会增加注册中心压力）\n    register-mode: instance\n    # 应用版本（随 application.version），用于版本路由与灰度\n    version: ${application.version:main}\n    # 关闭序列化安全检查，避免自定义实体校验报错（仅限内网环境，端口暴露到外部时必须开启）\n    serialize-check-status: DISABLE\n    # 不校验序列化类是否实现 Serializable\n    check-serializable: false\n  # RPC 实现类扫描包，按项目缩写拼接（如 system → com.maozi.system.*.api.impl.rpc）\n  scan:\n    base-packages: com.maozi.${application-project-abbreviation}.*.api.impl.rpc\n  # 通信协议配置\n  protocol:\n    # 通信协议：dubbo；需要 Triple/gRPC 时改为 tri\n    name: dubbo\n    # Dubbo 端口，-1 表示随机；固定端口用 APPLICATION_DUBBO_PORT 或 application.dubbo.port 指定\n    port: ${APPLICATION_DUBBO_PORT:${application.dubbo.port:-1}}\n  # 服务提供者配置\n  provider:\n    # 默认超时时间（毫秒）：30000 即 30s，联调环境容忍慢接口\n    timeout: 30000\n    # 自定义过滤器：服务端从 RPC 附件还原用户、链路等上下文\n    filter: applicationDubboContextLoadFilter\n    # 优先使用的序列化方式\n    prefer-serialization: hessian2\n    # 序列化方式\n    serialization: hessian2\n  # 服务消费者配置\n  consumer:\n    # 启动时不检查依赖的服务是否在线，解除服务启动顺序耦合\n    check: false\n    # 默认超时时间（毫秒），30s\n    timeout: 30000\n    # 失败后自动重试 1 次，非幂等接口需在 @DubboReference 上单独关闭\n    retries: 1\n    # 自定义过滤器：消费端将用户、链路等上下文写入 RPC 附件透传\n    filter: applicationDubboContextTransmitFilter\n  # 注册中心：复用 Nacos（与配置中心同实例），namespace 随环境隔离\n  registry:\n    address: nacos://${spring.cloud.nacos.discovery.server-addr}?namespace=${spring.cloud.nacos.discovery.namespace}', 'ced6b34ee1211a1a8988527017a0430a', '2026-10-28 13:18:35', '2026-11-24 08:55:11', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8582, 'cloud-nacos.yml', 'DEFAULT_GROUP', '# Nacos 服务发现配置（server-addr、namespace 由启动初始化器按环境写入）\nspring:\n  cloud:\n    nacos:\n      # 服务发现配置\n      discovery:\n        # 启用 Nacos 服务发现\n        enabled: true\n        # 启动时将本实例注册到注册中心\n        register-enabled: true\n        # 实例元数据：携带版本号，灰度路由按此筛选实例\n        metadata:\n          version: ${application.version:main}', 'fe9dc2a75e748eeb2a23b3f914658e4d', '2026-10-28 13:18:35', '2026-11-24 08:44:06', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8583, 'cloud-rocket.yml', 'DEFAULT_GROUP', '# RocketMQ 配置（当前未启用：无服务引入 stream 模块，接入 MQ 时替换 name-server）\nspring:\n  cloud:\n    stream:\n      rocketmq:\n        # RocketMQ Binder 配置\n        binder:\n          # access-key:    # 阿里云 AccessKey ID，按需配置\n          # secret-key:    # 阿里云 AccessKey Secret，按需配置\n          # NameServer 地址\n          name-server: localhost:9876\n# 以下为预留占位，未启用\n# rocketmq:\n  # instance:\n    # id:\n    # name:', '7ed1c9e411ede71a7a001c6cfa0fa149', '2026-10-28 13:18:35', '2026-11-24 08:44:42', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8584, 'cloud-sentinel.yml', 'DEFAULT_GROUP', '# Sentinel 流量防护配置（业务服务共用，网关见 maozi-cloud-gateway-service.yml）\n\n# RestTemplate 纳入 Sentinel 熔断限流（默认已开启）\nresttemplate:\n  sentinel:\n    enabled: true\n\n# Feign 接口接入 Sentinel 熔断降级\nfeign:\n  sentinel:\n    enabled: true\n\n# Sentinel 客户端：控制台接入、规则从 Nacos 加载\nspring:\n  cloud:\n    sentinel:\n      # 自定义键（非 Sentinel 官方属性）：Sentinel 应用名，同时作为下方规则 dataId 的前缀\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 应用启动即连接控制台（默认首次请求时才注册）\n      eager: true\n      # 与控制台的通信配置\n      transport:\n        # 客户端与控制台通信的本地端口，被占用时自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 资源名带 HTTP 方法前缀（如 GET:/user/info），区分同路径的不同请求方法\n      http-method-specify: true\n      # 规则数据源：规则存于 Nacos middleware 命名空间 SENTINEL_GROUP，变更后实时生效\n      # 各数据源通用字段：server-addr=Nacos 地址，namespace=命名空间，groupId=分组，\n      #                  dataId=规则文件名，rule-type=规则类型\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority', 'e089fa4e387e2e024d989e306ec67830', '2026-10-28 13:18:35', '2026-11-24 08:45:28', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8585, 'boot-lock.yml', 'DEFAULT_GROUP', '# 分布式锁配置（Redisson 客户端连接、锁默认超时）\nlock:\n  # Redisson 配置\n  redisson:\n    # 单节点 Redis 地址，复用 spring.data.redis 的地址与端口\n    address: redis://${spring.data.redis.host}:${spring.data.redis.port}\n    # Redis 密码\n    password: ${spring.data.redis.password}\n    # Redis 逻辑库编号\n    database: ${spring.data.redis.database:0}\n    # 集群模式：配置节点地址列表后自动启用，与 address 二选一\n    # node-addresses: redis://127.0.0.1:7000,redis://127.0.0.1:7001,redis://127.0.0.1:7002\n    # 获取锁的最长等待时间（秒），不配置默认 60\n    # waitTime: 60\n    # 锁的自动释放时间（秒），不配置默认 60\n    # leaseTime: 60', '3dd8b897d00f0f855638675d348e8b97', '2026-10-28 13:18:35', '2026-11-24 08:44:42', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8586, 'boot-monitor.yml', 'DEFAULT_GROUP', '# 监控配置：Spring Boot Admin 客户端注册、Actuator 端点与指标\nspring:\n  boot:\n    admin:\n      # Spring Boot Admin 客户端配置\n      client:\n        # SBA 服务端地址，启动后自动注册\n        url: http://${APPLICATION_MONITOR_SERVER:maozi-cloud-basic-monitor:2000}/monitor\n        # 注册到 SBA 服务端所用的账号，须与服务端 spring.security.user 一致\n        username: monitor\n        password: monitor\n        # 应用关闭时自动从 SBA 服务端注销\n        auto-deregistration: true\n        # 注册实例信息\n        instance:\n          # 注册地址优先使用 IP（项目已固定取 spring.cloud.client.ip-address，此项仅作兜底）\n          prefer-ip: true\n          # 实例元数据：SBA 控制台展示的环境与版本\n          metadata:\n            version: 环境:${application.environment:local} 版本:${application.version:main}\n            # 实例标签：环境、版本，可用于控制台筛选\n            tags:\n              environment: ${application.environment:local}\n              version: ${application.version:main}\n\n# 当前不生效：endpoints.<id>.enabled 为 Boot 2.x 旧属性，Dubbo 端点由下方 management.endpoint.dubbo.enabled 控制\nendpoints:\n  dubbo:\n    enabled: true\n\n# Actuator 端点与指标\nmanagement:\n  # info 端点展示 info.* 配置项\n  info.env.enabled: true\n  # Dubbo 健康检查配置\n  health:\n    dubbo:\n      status:\n        # Dubbo 健康检查默认项：内存\n        defaults: memory\n        # 附加检查项：系统负载、线程池\n        extras: load,threadpool\n  # Web 端点暴露配置\n  endpoints:\n    web:\n      exposure:\n        # 暴露全部 Web 端点\n        include: \'*\'\n  # 各端点开关配置\n  endpoint:\n    # env 端点展示配置项的值\n    env.show-values: always\n    # 启用 serviceregistry 端点：查看、切换服务注册状态\n    serviceregistry:\n      enabled: true\n    # 启用 shutdown 端点：支持通过 HTTP 关闭应用\n    shutdown:\n      enabled: true\n    # 启用 Dubbo 端点：元数据总览\n    dubbo:\n      enabled: true\n    # 启用 dubbo-shutdown 端点：优雅停机状态\n    dubbo-shutdown:\n      enabled: true\n    # 启用 dubbo-configs 端点：Dubbo 配置\n    dubbo-configs:\n      enabled: true\n    # 启用 dubbo-services 端点：已发布的服务\n    dubbo-services:\n      enabled: true\n    # 启用 dubbo-references 端点：已引用的服务\n    dubbo-references:\n      enabled: true\n    # 启用 dubbo-properties 端点：Dubbo 配置属性\n    dubbo-properties:\n      enabled: true\n    # 健康端点配置\n    health:\n      # 健康详情全部展示（含各组件状态）\n      show-details: ALWAYS\n      # 启用 K8s 存活、就绪探针分组\n      probes.enabled: true\n  # 指标配置\n  metrics:\n    # 指标公共标签：应用、实例、环境\n    tags:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}\n    # 指标分布配置\n    distribution:\n      # HTTP 服务端请求指标开启直方图，支持百分位统计\n      percentiles-histogram:\n        http:\n          server:\n            requests: \'true\'\n  # 观测（metrics、tracing）公共属性，与 metrics.tags 保持一致\n  observations:\n    key-values:\n      application: ${spring.application.name}\n      instances: ${spring.cloud.client.ip-address}\n      environment: ${application.environment}', 'c704d202c9b157bd86128f40ca93dadb', '2026-10-28 13:18:35', '2026-11-24 08:45:28', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8587, 'cloud-oauth.yml', 'DEFAULT_GROUP', '# 资源服务器 OAuth2：不透明令牌（Opaque Token）内省校验\nspring:\n  security:\n    oauth2:\n      resourceserver:\n        # 不透明令牌内省配置\n        opaquetoken:\n          # 内省调用方式（项目自定义键）：不配置或 rpc 走 Dubbo，其他值（如 http）走 Feign\n          # mode: http\n          # 以下两项为 Spring Security 默认内省器的属性；当前内省由自定义 OpaqueTokenIntrospector 完成，未被读取\n          client-id: system\n          client-secret: 123456', 'f925e2b395d0ec0f4ecac62de9317d38', '2026-10-28 13:18:35', '2026-11-24 08:44:42', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8588, 'boot-db.yml', 'DEFAULT_GROUP', '# 数据源与数据库访问配置：MySQL（HikariCP 连接池）、Flyway 建表迁移、MyBatis-Plus 及连表插件\nspring:\n  # 数据源配置\n  datasource:\n    # 连接池实现类：HikariCP（Spring Boot 默认连接池）\n    type: com.zaxxer.hikari.HikariDataSource\n    # MySQL 8 驱动类\n    driver-class-name: com.mysql.cj.jdbc.Driver\n    # JDBC 连接串，主机与库名支持环境变量覆盖，默认每服务一库（应用名-环境-db）\n    # 参数：useSSL=false 内网关闭 SSL；serverTimezone 指定时区；characterEncoding 指定编码；\n    #       nullCatalogMeansCurrent=true 元数据查询时 catalog 传 null 视为当前库，避免扫出所有库\n    url: jdbc:mysql://${APPLICATION_MYSQL_SERVER:maozi-cloud-basic-mysql:3306}/${APPLICATION_MYSQL_SERVER_DB:${spring.application.name}-${application.environment}-db}?useSSL=false&serverTimezone=Asia/Shanghai&characterEncoding=utf8&nullCatalogMeansCurrent=true\n    # 数据库账号，默认值仅供本地，其他环境通过环境变量覆盖\n    username: ${APPLICATION_MYSQL_SERVER_USERNAME:root}\n    # 数据库密码，默认值仅供本地，其他环境通过环境变量覆盖\n    password: ${APPLICATION_MYSQL_SERVER_PASSWORD:password}\n    # Hikari 连接池配置\n    hikari:\n      # 连接事务隔离级别：2=READ_COMMITTED（读已提交）\n      transaction-isolation: 2\n      # 最大连接数，按业务压测调整\n      maximum-pool-size: 15\n      # 获取连接的超时时间，超时抛出异常快速失败\n      connection-timeout: 6000\n      # 空闲连接回收超时；当前不生效：未配置 minimum-idle 时为固定大小连接池，HikariCP 忽略该项\n      idle-timeout: 300000\n      # 连接最大存活时间，需比 MySQL wait_timeout 小至少 60s，到期后异步关闭重建\n      max-lifetime: 540000\n\n  # Flyway 数据库版本迁移：启动时按版本号执行 classpath:db 下的脚本\n  flyway:\n    # 启用 Flyway\n    enabled: true\n    # 迁移历史表名，记录已执行的脚本版本\n    table: system_table_flyway\n    # 禁用 clean 操作，防止误删库\n    clean-disabled: true\n    # 允许乱序执行，可补跑历史遗漏的脚本\n    out-of-order: true\n    # 对非空且无迁移历史表的库自动打基线，不从零执行\n    baseline-on-migrate: true\n    # 基线版本号\n    baseline-version: 0\n    # 迁移脚本目录\n    locations: classpath:db\n    # 迁移脚本编码\n    encoding: UTF-8\n\n# MyBatis-Plus 配置\nmybatis-plus:\n  # Mapper XML 扫描路径，按项目缩写定位\n  mapper-locations: classpath:com/maozi/${application-project-abbreviation}/*/mapper/*.xml\n  # 枚举包扫描；当前不生效：MP 3.5.6 自动装配未读取该属性，枚举处理见下方 default-enum-type-handler\n  # typeEnumsPackage: com.maozi.${application-project-abbreviation}.*.enums\n  # MyBatis 配置\n  configuration:\n    # 数据库列下划线命名自动映射到驼峰属性\n    map-underscore-to-camel-case: true\n    # SQL 日志实现：自定义封装；需要直接输出到控制台时改用下方 StdOutImpl\n    log-impl: com.maozi.db.config.MybatisPlusLog\n    # 默认枚举类型处理器：MyBatis-Plus 通用枚举处理器\n    default-enum-type-handler: com.baomidou.mybatisplus.core.handlers.MybatisEnumTypeHandler\n    # log-impl: org.apache.ibatis.logging.stdout.StdOutImpl\n  # MyBatis-Plus 全局配置\n  global-config:\n    # 当前不生效：MP 3.5.6 的 GlobalConfig 无 refresh 属性\n    refresh: false\n    # 关闭 MyBatis-Plus 启动 banner\n    banner: false\n    # 数据库相关全局配置\n    db-config:\n      # 当前不生效：MP 3.5.6 的 DbConfig 无 dbType 属性\n      db-type: mysql\n      # 主键策略：数据库自增\n      id-type: AUTO\n      # 当前不生效：MP 3.5.6 无 field-strategy 属性\n      # 已拆分为 insert-strategy、update-strategy、where-strategy（默认均为 NOT_NULL）\n      field-strategy: NOT_NULL\n      # 当前不生效：MP 3.5.6 的 DbConfig 无 columnLike 属性\n      column-like: false\n      # SQL 关键字大写输出\n      capital-mode: true\n      # 逻辑已删除值：1=已删除\n      logic-delete-value: 1\n      # 逻辑未删除值：0=未删除\n      logic-not-delete-value: 0\n\n# MyBatis-Plus-Join 连表查询插件配置\nmybatis-plus-join:\n  # 关闭插件启动 banner\n  banner: false\n  # 连表查询主表默认别名\n  table-alias: main', 'eb997e6806173760051a1efe8f0f5dfe', '2026-10-28 13:18:35', '2026-11-24 08:46:38', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8589, 'maozi-cloud-system-service.yml', 'DEFAULT_GROUP', '# 系统服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: 系统服务\n  details: 管理 用户、角色、权限、系统配置 等功能\n\n# 项目级免认证接口白名单（在系统默认白名单基础上追加），多个路径逗号分隔\napplication-project-whitelist: /config/system/get\n\n# 项目公开信息（/config/system/get 接口返回，供前端展示）\napplication-project-system:\n  # 项目名称\n  projectName: 小猫子脚手架\n  # 公司名称\n  corporationName: 小猫子网络科技有限公司\n  # 系统图标地址\n  icon: http://dummyimage.com/100x100\n  # 运行环境，复用全局环境标识\n  environment: ${application.environment}\n  # 项目描述\n  description: 基于 Spring Cloud Alibaba + Dubbo 的一站式分布式解决方案开源封装，内置分布式应用开发所需全套组件，统一团队代码风格，保障代码质量，让开发者专注业务逻辑，实现高效快速开发。\n  # 版权声明\n  copyright: 本网站所有权归《${application-project-system.corporationName}》所有，请勿抄袭和抄袭\n\n# 文件上传配置\nspring.servlet.multipart:\n  # 单个上传文件的大小上限\n  max-file-size: 1MB\n\n# 文件存储配置\noss:\n  # 存储类型：aliyun 表示路由到阿里云 OSS 处理器\n  store-type: aliyun\n  # 阿里云 OSS 配置\n  aliyun:\n    # 阿里云 AccessKey ID，从环境变量注入\n    access-key-id: ${APPLICATION_ALIYUN_CLIENT_ID}\n    # 阿里云 AccessKey Secret，从环境变量注入\n    access-key-secret: ${APPLICATION_ALIYUN_CLIENT_SECRET}\n    # 地域\n    region: cn-beijing\n    # 访问域名\n    endpoint: https://oss-cn-beijing.aliyuncs.com\n    # 存储空间名称\n    bucket: maozi-cloud-bucket\n    #domain:    # 可选，CDN 自定义域名', 'f70f630ef9ecad4a89c15f440ffa112b', '2026-10-28 13:18:35', '2026-11-24 08:45:28', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8590, 'maozi-cloud-oauth-service.yml', 'DEFAULT_GROUP', '# 认证授权服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: 认证授权服务\n  details: 管理 三方认证授权、客户端 等功能\n\n# 项目级免认证接口白名单（在系统默认白名单基础上追加），多个路径逗号分隔；当前未配置\n# application-project-whitelist:', '40d5ca65ec89a93bccb4f530e0b720ac', '2026-10-28 13:18:35', '2026-11-24 08:44:42', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8591, 'maozi-cloud-gateway-service.yml', 'DEFAULT_GROUP', '# 网关服务自身配置：端口、Sentinel 网关流控、路由转发\napplication:\n  # 对外统一入口端口（作为 cloud-default.yml 中 server.port 的默认值）\n  port: 1100\n  # 服务标题与描述\n  title: 网关服务\n  details: 处理 流量分发、黑白名单、流控 等功能\n\n# Sentinel 网关流控配置\nspring:\n  cloud:\n    sentinel:\n      # 自定义键（非 Sentinel 官方属性）：Sentinel 应用名，同时作为下方规则 dataId 的前缀\n      name: ${spring.application.name}-${application.environment:local}-${application.version:main}\n      # 应用启动即连接控制台（默认首次请求时才注册）\n      eager: true\n      # 与控制台的通信配置\n      transport:\n        # 客户端与控制台通信的本地端口，被占用时自动顺延\n        port: 8719\n        # Sentinel 控制台地址\n        dashboard: ${APPLICATION_SENTINEL_SERVER:maozi-cloud-basic-sentinel:8858}\n      # 关闭通用 Web 流控过滤器，改由网关适配器（SentinelGatewayFilter）按路由、API 分组限流\n      filter:\n        enabled: false\n      # 规则数据源：规则存于 Nacos middleware 命名空间 SENTINEL_GROUP，变更后实时生效\n      # 各数据源通用字段：server-addr=Nacos 地址，namespace=命名空间，groupId=分组，\n      #                  dataId=规则文件名，rule-type=规则类型\n      datasource:\n        # 流控规则\n        flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-flow-rules.json\n            rule-type: flow\n        # 熔断降级规则\n        degrade:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-degrade-rules.json\n            rule-type: degrade\n        # 热点参数限流规则\n        param-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-param-rules.json\n            rule-type: param-flow\n        # 系统自适应保护规则\n        system:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            dataId: ${spring.cloud.sentinel.name}-system-rules.json\n            rule-type: system\n        # 黑白名单授权规则\n        authority:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            groupId: SENTINEL_GROUP\n            data-id: ${spring.cloud.sentinel.name}-authority-rules.json\n            rule-type: authority\n        # 网关流控规则（按路由或 API 分组限流）\n        gw-flow:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-flow-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-flow\n        # 网关 API 分组定义（将多个接口路径归为一组，供 gw-flow 引用）\n        gw-api-group:\n          nacos:\n            server-addr: ${spring.cloud.nacos.config.server-addr}\n            namespace: middleware\n            dataId: ${spring.cloud.sentinel.name}-gw-api-group-rules.json\n            groupId: SENTINEL_GROUP\n            rule-type: gw-api-group\n\n    # Spring Cloud Gateway 配置\n    gateway:\n      # 网关 HTTP 客户端配置\n      httpclient:\n        # 连接后端服务的超时时间（毫秒）\n        connect-timeout: 1000\n        # 等待后端响应的超时时间\n        response-timeout: 30s\n\n      # 服务发现路由配置\n      discovery:\n        locator:\n          # 按服务名自动创建路由（/服务名/** 转发到对应服务）\n          enabled: true\n\n      # 默认过滤器：对所有路由生效\n      default-filters:\n      # 去掉第一段路径前缀后再转发（/system/xxx → /xxx）\n      - StripPrefix=1\n      # 失败重试过滤器\n      - name: Retry\n        # 重试参数\n        args:\n          # 重试次数\n          retries: 1\n          # 按状态码系列重试：设为 INFORMATIONAL（1xx）即不按系列重试\n          series: INFORMATIONAL\n          # 仅 GET、POST 请求重试\n          methods:\n            - GET\n            - POST\n          # 命中以下后端状态码时重试：502、504、503\n          statuses:\n            - BAD_GATEWAY\n            - GATEWAY_TIMEOUT\n            - SERVICE_UNAVAILABLE\n          # 命中以下异常时重试：连接失败、未找到服务实例、连接被提前关闭\n          exceptions:\n            - java.net.ConnectException\n            - org.springframework.cloud.gateway.support.NotFoundException\n            - reactor.netty.http.client.PrematureCloseException\n\n      # 显式路由：路径前缀 → 注册中心服务（lb:// 表示负载均衡），新增服务照此添加\n      routes:\n        # 系统服务\n        - id: MAOZI-CLOUD-SYSTEM\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-system-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/system/**\n        # 认证服务\n        - id: MAOZI-CLOUD-OAUTH\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-oauth-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/oauth/**\n        # AI 服务\n        - id: MAOZI-CLOUD-AI-SERVICE\n          # 目标服务，lb:// 表示按服务名从注册中心负载均衡\n          uri: lb://maozi-cloud-ai-service\n          # 断言：匹配的路径前缀\n          predicates:\n          - Path=/ai/**', '317181f0d5c338887fcff96f25b8c6d4', '2026-10-28 13:18:35', '2026-11-24 08:54:45', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8592, 'cloud-seata.yml', 'DEFAULT_GROUP', '# Seata 分布式事务客户端配置\nseata:\n  # 启用 Seata 自动装配，@GlobalTransactional 才会生效\n  enabled: true\n  # Seata 应用标识，取服务名\n  application-id: ${spring.application.name}\n  # 事务分组（maozi-cloud-{环境}-tx-group），须与 seata.properties 中的 service.vgroupMapping 映射对应\n  tx-service-group: maozi-cloud-${application.environment}-tx-group\n  # Seata 配置中心：从 Nacos middleware 命名空间 SEATA_GROUP 读取 seata.properties\n  config:\n    # 配置中心类型：Nacos\n    type: nacos\n    # Nacos 连接信息\n    nacos:\n      # Nacos 地址，复用配置中心地址\n      serverAddr: ${spring.cloud.nacos.config.server-addr}\n      # 命名空间\n      namespace: middleware\n      # 分组\n      group: SEATA_GROUP\n      # 配置文件 dataId\n      dataId: seata.properties\n      # Nacos 访问账号\n      username: \'nacos\'\n      # Nacos 访问密码\n      password: \'nacos\'\n  # Seata 注册中心：按应用名 maozi-cloud-basic-seata 在 Nacos 中发现 TC 服务端\n  registry:\n    # 注册中心类型：Nacos\n    type: nacos\n    # Nacos 连接信息\n    nacos:\n      # TC 服务端注册到 Nacos 的应用名\n      application: maozi-cloud-basic-seata\n      # Nacos 地址，复用注册中心地址\n      server-addr: ${spring.cloud.nacos.discovery.server-addr}\n      # 命名空间\n      namespace: middleware\n      # 分组\n      group: SEATA_GROUP\n      # Nacos 访问账号\n      username: \'nacos\'\n      # Nacos 访问密码\n      password: \'nacos\'', '79de6eb2915b3d56521ac152560285fe', '2026-10-28 13:18:35', '2026-11-24 08:53:59', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8593, 'maozi-cloud-ai-service.yml', 'DEFAULT_GROUP', '# AI 服务自身配置\n# title/details：服务标题与描述，用于 Swagger 文档标题与描述\napplication:\n  title: AI服务\n  details: 与AI交互、管理AI对话记忆、AI知识库、AI提示词等\n\n# Spring AI 模型接入：当前启用 DashScope（阿里云百炼），zhipuai、openai 为备选，切换时需同时引入对应 starter\nspring:\n  ai:\n    # 智谱 AI（备选，默认不启用）\n    # zhipuai:\n    #   base-url: https://api.z.ai/api/paas\n    #   api-key:\n    #   chat:\n    #     options:\n    #       model: glm-5.2\n    #   embedding:\n    #     enabled: false\n    # 阿里云百炼（DashScope）\n    dashscope:\n      # API Key，从环境变量注入，禁止写死在配置里\n      api-key: ${APPLICATION_AI_DASHSCOPE_KEY}\n      # 对话模型配置\n      chat:\n        # 启用对话模型\n        enabled: true\n        # 模型参数\n        options:\n          # 文本对话模型\n          model: qwen-max\n          # 图生文模型（项目自定义键），对话携带图片时切换使用\n          text_image_model: qwen-vl-max\n      # 向量模型，默认关闭，知识库、RAG 场景再开启\n      embedding:\n        enabled: false\n        # 模型参数\n        options:\n          # 向量模型\n          model: text-embedding-v3\n          # 向量维度\n          dimensions: 1024\n    # OpenAI（备选，默认不启用）\n    # openai:\n    #   base-url:\n    #   api-key:\n    #   chat:\n    #     options:\n    #       model: gpt\n    #   embedding:\n    #     enabled: false', 'ecf3106617456bcb661e77bc6e796edd', '2026-10-28 13:18:35', '2026-11-24 08:45:28', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8594, 'boot-snailjob.yml', 'DEFAULT_GROUP', '# SnailJob 客户端配置（分布式任务调度、重试）\nsnail-job:\n  # SnailJob 服务端连接信息\n  server:\n    # 服务端地址（IP 或域名），集群时需前置负载均衡\n    host: ${APPLICATION_SNAIL_JOB_SERVER:maozi-cloud-basic-snailjob}\n    # 服务端通讯端口（非管理后台页面端口）\n    port: 17888\n  # 命名空间，须与服务端一致（此处直接使用环境名）\n  namespace: ${application.environment}\n  # 接入组名，须与服务端一致\n  group: ${spring.application.name}-${application.version:main}\n  # 接入组令牌，须与服务端一致\n  token: SJ_Wyz3dmsdbDOkDujOTSSoBjGQP1BMsVnj\n  # 客户端绑定 IP，服务端须可访问；不配置则自动获取，服务端无法调度客户端时再手动指定\n  # host: 127.0.0.1\n  # 客户端通讯端口\n  port: 17889\n  # 实例标签：携带版本号，可在控制台按版本筛选\n  labels:\n    version: ${application.version:main}', '980eaf03e83651def53ba015a5740e97', '2026-10-28 13:18:35', '2026-11-24 08:44:42', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8595, 'boot-xxljob.yml', 'DEFAULT_GROUP', '# XXL-Job 执行器配置（引入 maozi-cloud-config-xxljob 模块的服务生效）\nxxl:\n  job:\n    # 与调度中心一致的通讯令牌\n    accessToken: default_token\n    # 调度中心配置\n    admin:\n      # 调度中心地址，多个地址逗号分隔\n      addresses: http://${APPLICATION_XXLJOB_SERVER:maozi-cloud-basic-xxljob:12000}/xxljob\n    # 执行器配置\n    executor:\n      # 执行器AppName（应用名-环境-版本），调度中心按此注册执行器\n      appname: ${spring.application.name}-${application.environment}-${application.version}\n      # 当前不生效：项目 JobProperties 无对应字段，仅 ip 参与注册\n      address: \"\"\n      # 执行器 IP，留空则自动获取\n      ip: \"\"\n      # 执行器端口，小于等于 0 时自动获取可用端口\n      port: 0\n      # 执行器日志文件路径\n      logpath: ./data/xxl-job\n      # 执行器日志保留天数，小于 3 时不清理\n      logRetentionDays: 30', '8dd94cebdc9d6305036b56662264462e', '2026-10-28 13:18:35', '2026-11-24 08:44:42', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8596, 'maozi-cloud-basic-monitor.yml', 'DEFAULT_GROUP', '# 监控服务自身配置（Spring Boot Admin 服务端）\n# title/details：服务标题与描述\napplication:\n  title: 监控服务\n  details: 监控 JVM、运行状态、配置、连接中间件状态 等功能\n\n# Spring Boot Admin 服务端配置，控制台访问地址 :2000/monitor\nspring:\n  boot:\n    admin:\n      # 控制台上下文路径（nginx 将 /monitor/ 原样透传）\n      context-path: /monitor\n      # 服务发现配置\n      discovery:\n        # 关闭通过服务发现自动注册，改为客户端主动注册\n        enabled: false\n  # 控制台登录账号，同时作为客户端注册（见 boot-monitor.yml）所用的账号密码\n  security:\n    user:\n      name: monitor\n      password: monitor\n\n# Actuator 端点基础路径，与控制台同挂在 /monitor 下\nmanagement:\n  endpoints:\n    web:\n      base-path: /monitor/actuator', 'e9e024e848e5bbdb49b5d5af1cfc3a57', '2026-10-28 13:18:35', '2026-11-24 08:53:59', NULL, '192.168.65.1', '', 'local', NULL, NULL, NULL, 'yaml', NULL, '');
INSERT INTO `config_info` (`id`, `data_id`, `group_id`, `content`, `md5`, `gmt_create`, `gmt_modified`, `src_user`, `src_ip`, `app_name`, `tenant_id`, `c_desc`, `c_use`, `effect`, `type`, `c_schema`, `encrypted_data_key`) VALUES (8597, 'com.maozi.oauth.token.api.rpc.RpcOauthTokenService', 'mapping', 'dubbo-maozi-cloud-oauth-service', '0e3764c49fba5182223c875f125ce601', '2026-10-28 15:36:15', '2026-10-28 15:36:15', NULL, '172.18.0.13', '', 'prod', NULL, NULL, NULL, 'text', NULL, '');
